window.H=window.H||{};H[30]={"30회-2차-081":{"한줄":"물이 고이거나 상시 물을 저장하는 저수지·호수 등의 토지와 연·왕골 등이 자생하는 배수가 잘 되지 않는 토지는 유지(溜池)다(영 제58조제19호).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제19호","원문":"유지(溜池): 물이 고이거나 상시적으로 물을 저장하고 있는 댐ㆍ저수지ㆍ소류지(沼溜地)ㆍ호수ㆍ연못 등의 토지와 연ㆍ왕골 등이 자생하는 배수가 잘 되지 아니하는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제20호","원문":"양어장: 육상에 인공으로 조성된 수산생물의 번식 또는 양식을 위한 시설을 갖춘 부지와 이에 접속된 부속시설물의 부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제18호","원문":"구거: 용수(用水) 또는 배수(排水)를 위하여 일정한 형태를 갖춘 인공적인 수로ㆍ둑 및 그 부속시설물의 부지와 자연의 유수(流水)가 있거나 있을 것으로 예상되는 소규모 수로부지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제2호","원문":"답: 물을 상시적으로 직접 이용하여 벼ㆍ연(蓮)ㆍ미나리ㆍ왕골 등의 식물을 주로 재배하는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제58조제24호","원문":"유원지: 일반 공중의 위락ㆍ휴양 등에 적합한 시설물을 종합적으로 갖춘 수영장ㆍ유선장(遊船場)ㆍ낚시터ㆍ어린이놀이터ㆍ동물원ㆍ식물원ㆍ민속촌ㆍ경마장ㆍ야영장 등의 토지와 이에 접속된 부속시설물의 부지. 다만, 이들 시설과의 거리 등으로 보아 독립적인 것으로 인정되는 숙식시설 및 유기장(遊技場)의 부지와 하천ㆍ구거 또는 유지[공유(公有)인 것으로 한정한다]로 분류되는 것은 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"발문의 토지는 유지(溜池)다(영 제58조제19호)."},{"번호":2,"판정":"틀림","설명":"양어장은 육상에 인공으로 조성된 수산생물의 번식·양식 시설을 갖춘 부지다(영 제58조제20호)."},{"번호":3,"판정":"틀림","설명":"구거는 용수·배수를 위한 인공 수로·둑·부속시설물의 부지와 소규모 수로부지다(영 제58조제18호)."},{"번호":4,"판정":"틀림","설명":"답은 물을 상시적으로 직접 이용하여 벼·연·미나리·왕골 등을 주로 재배하는 토지다(영 제58조제2호)."},{"번호":5,"판정":"틀림","설명":"유원지는 수영장·유선장·낚시터·동물원 등 위락·휴양 시설을 종합적으로 갖춘 토지다(영 제58조제24호)."}],"개념":[{"종류":"표","제목":"물·시설 부지 지목 구분(영 제58조)","머리":["지목","포함","제외·주의"],"행":[["광천지","온수·약수·석유류 등이 용출되는 용출구와 그 유지에 사용되는 부지","송수관·송유관·저장시설의 부지는 제외"],["수도용지","물을 정수하여 공급하기 위한 취수·저수·도수·정수·송수 및 배수 시설의 부지와 접속 부속시설물의 부지","-"],["유지","물이 고이거나 상시 물을 저장하는 댐·저수지·소류지·호수·연못 등과 연·왕골 등이 자생하는 배수가 잘 되지 않는 토지","연·왕골 등을 상시 직접 이용하여 재배하면 답"],["답","물을 상시적으로 직접 이용하여 벼·연·미나리·왕골 등을 주로 재배하는 토지","-"],["구거","용수·배수를 위한 인공 수로·둑·부속시설물의 부지, 유수가 있거나 있을 것으로 예상되는 소규모 수로부지","-"],["하천","자연의 유수가 있거나 있을 것으로 예상되는 토지","-"],["양어장","육상에 인공으로 조성된 수산생물의 번식·양식 시설을 갖춘 부지와 접속 부속시설물의 부지","-"]]}],"함정":"연·왕골이 나오는 지목은 둘이다. 상시 직접 이용해 재배하면 답이고, 자생하는 배수 불량 토지면 유지다."},"30회-2차-091":{"한줄":"제방의 부호는 \"제\"이므로(규칙 제64조) ④가 옳다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제64조","원문":"지목을 지적도 및 임야도(이하 \"지적도면\"이라 한다)에 등록하는 때에는 다음의 부호로 표기하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"광천지의 부호는 \"광\"이다(규칙 제64조)."},{"번호":2,"판정":"틀림","설명":"공장용지의 부호는 \"장\"이다(규칙 제64조)."},{"번호":3,"판정":"틀림","설명":"유원지의 부호는 \"원\"이다(규칙 제64조)."},{"번호":4,"판정":"옳음","설명":"제방의 부호는 \"제\"다(규칙 제64조)."},{"번호":5,"판정":"틀림","설명":"도로의 부호는 \"도\"다(규칙 제64조)."}],"개념":[{"종류":"표","제목":"지목 28종과 지적도면 부호(규칙 제64조)","머리":["지목","부호","지목","부호"],"행":[["전","전","철도용지","철"],["답","답","제방","제"],["과수원","과","하천","천"],["목장용지","목","구거","구"],["임야","임","유지","유"],["광천지","광","양어장","양"],["염전","염","수도용지","수"],["대","대","공원","공"],["공장용지","장","체육용지","체"],["학교용지","학","유원지","원"],["주차장","차","종교용지","종"],["주유소용지","주","사적지","사"],["창고용지","창","묘지","묘"],["도로","도","잡종지","잡"]]}],"함정":"공장용지(장)와 유원지(원)는 이름의 두 번째 글자를, 광천지(광)와 도로(도)는 첫 글자를 쓴다. 하천은 두 번째 글자 천이지만 제방(제)·구거(구)·유지(유)는 첫 글자다."},"30회-2차-083":{"한줄":"지상경계를 새로 정한 경우 경계점 위치 설명도와 경계점표지의 종류 등을 등록하여 관리하는 장부는 지상경계점등록부다(법 제65조제2항, 규칙 제60조제2항).","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제65조제2항","원문":"지적소관청은 토지의 이동에 따라 지상경계를 새로 정한 경우에는 다음 각 호의 사항을 등록한 지상경계점등록부를 작성ㆍ관리하여야 한다. 1. 토지의 소재 2. 지번 3. 경계점 좌표(경계점좌표등록부 시행지역에 한정한다) 4. 경계점 위치 설명도 5. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제60조제2항","원문":"법 제65조제2항제5호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 공부상 지목과 실제 토지이용 지목 2. 경계점의 사진 파일 3. 경계점표지의 종류 및 경계점 위치"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지이동조사부는 토지이동현황을 직권으로 조사한 때 이동현황을 적는 장부다(규칙 제59조제2항)."},{"번호":2,"판정":"틀림","설명":"부동산종합공부는 토지·건축물·토지이용·가격·권리 정보를 등록하는 공부다(법 제76조의3, 영 제62조의2)."},{"번호":3,"판정":"틀림","설명":"경계점좌표등록부는 토지의 소재, 지번, 좌표 등을 등록하는 지적공부다(법 제73조)."},{"번호":4,"판정":"옳음","설명":"경계점 위치 설명도, 경계점표지의 종류 및 경계점 위치 등은 지상경계점등록부에 등록한다(법 제65조제2항, 규칙 제60조제2항)."},{"번호":5,"판정":"틀림","설명":"토지이동정리 결의서는 지적공부를 정리할 때 토지이동 조서를 첨부하는 서식이다(규칙 제59조제4항)."}],"개념":[{"종류":"표","제목":"지상경계점등록부(법 제65조제2항, 규칙 제60조제2항)","머리":["구분","등록사항"],"행":[["토지의 소재","법 제65조제2항제1호"],["지번","법 제65조제2항제2호"],["경계점 좌표","경계점좌표등록부 시행지역에 한정(제3호)"],["경계점 위치 설명도","법 제65조제2항제4호"],["공부상 지목과 실제 토지이용 지목","규칙 제60조제2항제1호"],["경계점의 사진 파일","규칙 제60조제2항제2호"],["경계점표지의 종류 및 경계점 위치","규칙 제60조제2항제3호"]]},{"종류":"표","제목":"지적공부별 등록사항(법 제71조~제73조, 규칙 제68조·제69조·제71조)","머리":["공부","등록사항"],"행":[["토지대장·임야대장","토지의 소재, 지번, 지목, 면적, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 지적도 또는 임야도의 번호와 필지별 장번호 및 축척, 토지의 이동사유, 토지소유자가 변경된 날과 그 원인, 토지등급 또는 기준수확량등급과 설정·수정 연월일, 개별공시지가와 그 기준일"],["공유지연명부","토지의 소재, 지번, 소유권 지분, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 필지별 공유지연명부의 장번호, 토지소유자가 변경된 날과 그 원인"],["대지권등록부","토지의 소재, 지번, 대지권 비율, 소유자의 성명 또는 명칭·주소·주민등록번호, 토지의 고유번호, 전유부분의 건물표시, 건물의 명칭, 집합건물별 대지권등록부의 장번호, 토지소유자가 변경된 날과 그 원인, 소유권 지분"],["경계점좌표등록부","토지의 소재, 지번, 좌표, 토지의 고유번호, 지적도면의 번호, 필지별 경계점좌표등록부의 장번호, 부호 및 부호도"],["지적도·임야도","토지의 소재, 지번, 지목, 경계, 지적도면의 색인도, 지적도면의 제명 및 축척, 도곽선과 그 수치, 좌표에 의하여 계산된 경계점 간의 거리(경계점좌표등록부 시행지역), 삼각점 및 지적기준점의 위치, 건축물 및 구조물 등의 위치"]]}],"함정":"경계점 위치 설명도와 경계점표지의 종류는 지상경계점등록부의 항목이다. 경계점좌표등록부에는 좌표가 들어가고, 토지이동조사부와 토지이동정리 결의서는 직권 조사·정리에 쓰는 서식이다."},"30회-2차-086":{"한줄":"정보처리시스템으로 기록·저장된 지적공부의 열람·등본 발급은 특별자치시장, 시장·군수 또는 구청장이나 읍·면·동의 장에게 신청하므로(법 제75조제1항) 시·도지사를 든 ①이 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제75조제1항","원문":"지적공부를 열람하거나 그 등본을 발급받으려는 자는 해당 지적소관청에 그 열람 또는 발급을 신청하여야 한다. 다만, 정보처리시스템을 통하여 기록ㆍ저장된 지적공부(지적도 및 임야도는 제외한다)를 열람하거나 그 등본을 발급받으려는 경우에는 특별자치시장, 시장ㆍ군수 또는 구청장이나 읍ㆍ면ㆍ동의 장에게 신청할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제76조의3","원문":"지적소관청은 부동산종합공부에 다음 각 호의 사항을 등록하여야 한다. 1. 토지의 표시와 소유자에 관한 사항: 이 법에 따른 지적공부의 내용 2. 건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만 해당한다): 「건축법」 제38조에 따른 건축물대장의 내용 3. 토지의 이용 및 규제에 관한 사항: 「토지이용규제 기본법」 제10조에 따른 토지이용계획확인서의 내용 4. 부동산의 가격에 관한 사항: 「부동산 가격공시에 관한 법률」 제10조에 따른 개별공시지가, 같은 법 제16조, 제17조 및 제18조에 따른 개별주택가격 및 공동주택가격 공시내용 5. 그 밖에 부동산의 효율적 이용과 부동산과 관련된 정보의 종합적 관리ㆍ운영을 위하여 필요한 사항으로서 대통령령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"규칙 제74조제2항","원문":"법 제76조의4에 따라 부동산종합공부를 열람하거나 부동산종합공부 기록사항의 전부 또는 일부에 관한 증명서(이하 \"부동산종합증명서\"라 한다)를 발급받으려는 자는 별지 제71호서식의 지적공부ㆍ부동산종합공부 열람ㆍ발급 신청서(전자문서로 된 신청서를 포함한다)를 지적소관청 또는 읍ㆍ면ㆍ동장에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신청 상대는 특별자치시장, 시장·군수 또는 구청장이나 읍·면·동의 장이다. 시·도지사는 포함되지 않는다(법 제75조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"부동산종합공부에는 지적공부의 내용 중 토지의 표시와 소유자에 관한 사항을 등록한다(법 제76조의3제1호)."},{"번호":3,"판정":"옳음","설명":"부동산종합공부의 열람과 증명서 발급은 열람·발급 신청서(전자문서 포함)를 지적소관청 또는 읍·면·동장에게 제출한다(규칙 제74조제2항)."},{"번호":4,"판정":"옳음","설명":"토지이용계획확인서의 내용 중 토지의 이용 및 규제에 관한 사항을 등록한다(법 제76조의3제3호)."},{"번호":5,"판정":"옳음","설명":"건축물대장의 내용 중 건축물의 표시와 소유자에 관한 사항을 등록한다. 토지에 건축물이 있는 경우만 해당한다(법 제76조의3제2호)."}],"개념":[{"종류":"표","제목":"부동산종합공부의 등록사항(법 제76조의3, 영 제62조의2)","머리":["호","등록사항","내용 출처"],"행":[["1","토지의 표시와 소유자에 관한 사항","공간정보법에 따른 지적공부의 내용"],["2","건축물의 표시와 소유자에 관한 사항(토지에 건축물이 있는 경우만)","건축법 제38조에 따른 건축물대장의 내용"],["3","토지의 이용 및 규제에 관한 사항","토지이용규제 기본법 제10조에 따른 토지이용계획확인서의 내용"],["4","부동산의 가격에 관한 사항","부동산 가격공시에 관한 법률 제10조에 따른 개별공시지가, 같은 법 제16조·제17조·제18조에 따른 개별주택가격 및 공동주택가격 공시내용"],["5","부동산의 효율적 이용과 정보의 종합적 관리·운영을 위하여 필요한 사항","부동산등기법 제48조에 따른 부동산의 권리에 관한 사항(영 제62조의2)"]]},{"종류":"표","제목":"지적공부 열람·등본 발급 신청(법 제75조제1항, 규칙 제74조)","머리":["구분","신청 상대"],"행":[["원칙","해당 지적소관청"],["정보처리시스템으로 기록·저장된 지적공부(지적도·임야도 제외)","특별자치시장, 시장·군수 또는 구청장이나 읍·면·동의 장"],["지적도·임야도","해당 지적소관청"],["신청서","지적공부·부동산종합공부 열람·발급 신청서(전자문서 포함)"]]}],"함정":"정보처리시스템 기록분은 지적소관청 외에 읍·면·동의 장에게도 신청할 수 있지만 지적도·임야도는 제외되고, 시·도지사는 신청 상대가 아니다."},"30회-2차-084":{"한줄":"바다로 된 토지의 등록말소 신청 통지를 받은 토지소유자가 통지를 받은 날부터 90일 이내에 신청하지 않으면 지적소관청이 등록을 말소하므로(법 제82조제2항) 60일이라고 한 ④가 틀리다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제82조제1항","원문":"지적소관청은 지적공부에 등록된 토지가 지형의 변화 등으로 바다로 된 경우로서 원상(原狀)으로 회복될 수 없거나 다른 지목의 토지로 될 가능성이 없는 경우에는 지적공부에 등록된 토지소유자에게 지적공부의 등록말소 신청을 하도록 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제82조제2항","원문":"지적소관청은 제1항에 따른 토지소유자가 통지를 받은 날부터 90일 이내에 등록말소 신청을 하지 아니하면 대통령령으로 정하는 바에 따라 등록을 말소한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제82조제3항","원문":"지적소관청은 제2항에 따라 말소한 토지가 지형의 변화 등으로 다시 토지가 된 경우에는 대통령령으로 정하는 바에 따라 토지로 회복등록을 할 수 있다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"영 제68조","원문":"법 제82조제2항에 따라 토지소유자가 등록말소 신청을 하지 아니하면 지적소관청이 직권으로 그 지적공부의 등록사항을 말소하여야 한다. ② 지적소관청은 법 제82조제3항에 따라 회복등록을 하려면 그 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따라야 한다. ③ 제1항 및 제2항에 따라 지적공부의 등록사항을 말소하거나 회복등록하였을 때에는 그 정리 결과를 토지소유자 및 해당 공유수면의 관리청에 통지하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"법 제89조제1항","원문":"지적소관청은 제64조제2항(신규등록은 제외한다), 제66조제2항, 제82조, 제83조제2항, 제84조제2항 또는 제85조제2항에 따른 사유로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁은 국가가 국가를 위하여 하는 등기로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"원상 회복될 수 없는 경우 지적소관청은 토지소유자에게 등록말소 신청을 하도록 통지한다(법 제82조제1항)."},{"번호":2,"판정":"옳음","설명":"등록말소로 토지의 표시 변경에 관한 등기가 필요하면 지체 없이 관할 등기관서에 촉탁한다(법 제89조제1항)."},{"번호":3,"판정":"옳음","설명":"회복등록은 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따른다(영 제68조제2항)."},{"번호":4,"판정":"틀림","설명":"신청 기한은 통지를 받은 날부터 90일 이내다. 60일이 아니다. 신청이 없으면 지적소관청이 직권으로 말소한다(법 제82조제2항, 영 제68조제1항)."},{"번호":5,"판정":"옳음","설명":"말소하거나 회복등록하였을 때에는 정리 결과를 토지소유자 및 해당 공유수면의 관리청에 통지한다(영 제68조제3항)."}],"개념":[{"종류":"흐름","제목":"바다로 된 토지의 등록말소와 회복(법 제82조, 영 제68조)","단계":[{"이름":"통지","설명":"지형의 변화 등으로 바다로 된 토지가 원상으로 회복될 수 없거나 다른 지목의 토지로 될 가능성이 없으면 소유자에게 등록말소 신청을 하도록 통지(법 제82조제1항)"},{"이름":"신청","설명":"통지를 받은 날부터 90일 이내에 등록말소 신청(법 제82조제2항)"},{"이름":"직권 말소","설명":"신청이 없으면 지적소관청이 직권으로 등록사항을 말소(영 제68조제1항)"},{"이름":"등기촉탁","설명":"토지의 표시 변경에 관한 등기가 필요하면 지체 없이 관할 등기관서에 촉탁(법 제89조제1항)"},{"이름":"정리 결과 통지","설명":"토지소유자 및 해당 공유수면의 관리청에 통지(영 제68조제3항)"},{"이름":"회복등록","설명":"말소한 토지가 다시 토지가 된 경우 지적측량성과 및 등록말소 당시의 지적공부 등 관계 자료에 따라 회복등록(법 제82조제3항, 영 제68조제2항)"}]}],"함정":"④는 직권 말소라는 후단은 맞고 전단의 기한만 60일로 바꿨다. 신청 기한은 통지를 받은 날부터 90일이다."},"30회-2차-001":{"한줄":"무등록 중개업자에게 중개를 의뢰한 거래당사자는 무등록 중개행위의 공동정범으로 처벌되지 않으므로 ③이 틀리다.","근거":[{"법령":"공인중개사법","조문":"제2조제5호","원문":"\"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제12조제2항","원문":"개업공인중개사등은 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 될 수 없다."},{"법령":"공인중개사법","조문":"제2조제1호","원문":"\"중개\"라 함은 제3조에 따른 중개대상물에 대하여 거래당사자간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 알선하는 것을 말한다."},{"법령":"공인중개사법","조문":"제48조제1호","원문":"제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자"},{"법령":"공인중개사법","조문":"제33조제1항제2호","원문":"제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위"},{"판례":"대법원 판례(무등록 중개업자에게 의뢰한 당사자)","요지":"무등록 중개업자에게 중개를 의뢰한 거래당사자는 무등록 중개업을 한 자의 공동정범으로 처벌되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소속공인중개사의 정의와 같다(제2조제5호)."},{"번호":2,"판정":"옳음","설명":"개업공인중개사인 법인의 사원·임원인 공인중개사는 소속공인중개사에 포함된다(제2조제5호)."},{"번호":3,"판정":"틀림","설명":"처벌 대상은 개설등록 없이 중개업을 한 자(제48조제1호)이고, 의뢰한 거래당사자는 공동정범이 되지 않는다는 것이 판례다. 개업공인중개사가 무등록 업자임을 알면서 중개를 의뢰받는 행위는 제33조제1항제2호의 금지행위다."},{"번호":4,"판정":"옳음","설명":"개업공인중개사등은 다른 개업공인중개사의 소속공인중개사·중개보조원 또는 개업공인중개사인 법인의 사원·임원이 될 수 없다(제12조제2항)."},{"번호":5,"판정":"옳음","설명":"지역권의 설정·취득도 권리의 득실변경에 관한 행위이고, 중개는 이를 알선하는 것이다(제2조제1호)."}],"개념":[{"종류":"표","제목":"중개업 관련 용어 정의","머리":["용어","정의의 핵심","조문"],"행":[["중개","중개대상물에 대한 매매·교환·임대차 등 권리 득실변경 행위의 알선","제2조제1호"],["공인중개사","공인중개사자격을 취득한 자(개설등록 여부 무관)","제2조제2호"],["중개업","다른 사람의 의뢰, 일정한 보수, 업으로 중개","제2조제3호"],["개업공인중개사","중개사무소 개설등록을 한 자(자격증 소지 여부는 요건이 아님)","제2조제4호"],["소속공인중개사","개업공인중개사 소속 공인중개사. 법인의 사원·임원인 공인중개사 포함. 중개업무 수행 또는 보조","제2조제5호"],["중개보조원","공인중개사 아닌 자로서 현장안내·일반서무 등 단순 업무 보조","제2조제6호"]]},{"종류":"표","제목":"이중등록·이중소속·사무소 설치 제한","머리":["금지 내용","조문","벌칙"],"행":[["이중으로 중개사무소 개설등록을 하여 중개업을 함","제12조제1항","제49조제1항 1년 이하 징역 또는 1천만원 이하 벌금(이중등록)"],["다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 됨","제12조제2항","둘 이상의 중개사무소에 소속된 자는 제49조제1항 적용"],["등록관청 관할 구역 안에 중개사무소를 둘 이상 둠","제13조제1항","제49조제1항 1년 이하 징역 또는 1천만원 이하 벌금"],["천막 등 이동이 쉬운 임시 중개시설물을 설치함","제13조제2항","제49조제1항 1년 이하 징역 또는 1천만원 이하 벌금"]]}],"함정":"의뢰인도 무등록 업자와 함께 처벌받는다고 생각해 ③을 옳게 본다. 제48조제1호는 개설등록 없이 중개업을 한 자를 처벌하는 규정이고, 의뢰인은 대상이 아니다."},"30회-2차-004":{"한줄":"미채굴광물, 온천수, 금전채권, 점유는 모두 제3조와 시행령 제2조에 열거된 중개대상물이 아니어서 ㄱ, ㄴ, ㄷ, ㄹ이 정답이다.","근거":[{"법령":"공인중개사법","조문":"제3조","원문":"1. 토지 2. 건축물 그 밖의 토지의 정착물 3. 그 밖에 대통령령으로 정하는 재산권 및 물건"},{"법령":"공인중개사법 시행령","조문":"제2조","원문":"1. 「입목에 관한 법률」에 따른 입목 2. 「공장 및 광업재단 저당법」에 따른 공장재단 및 광업재단"},{"판례":"대법원 판례(중개대상물이 아닌 것)","요지":"금전채권과 영업상의 이점 같은 무형의 가치는 중개대상물이 아니다. 중개대상물은 법 제3조와 시행령 제2조로 한정된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄷ, ㄹ도 중개대상물이 아니라 ㄱ, ㄴ만으로는 부족하다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄴ도 중개대상물이 아니라 ㄷ, ㄹ만으로는 부족하다."},{"번호":3,"판정":"틀림","설명":"ㄷ(금전채권)이 빠져 있다."},{"번호":4,"판정":"틀림","설명":"ㄱ(미채굴광물)이 빠져 있다."},{"번호":5,"판정":"옳음","설명":"네 보기 모두 중개대상물에 해당하지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"미채굴광물은 중개대상물로 열거되지 않는다."},{"기호":"ㄴ","판정":"옳음","설명":"온천수는 중개대상물로 열거되지 않는다."},{"기호":"ㄷ","판정":"옳음","설명":"금전채권은 중개대상물이 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"점유는 물건이나 열거된 재산권이 아니라서 중개대상물이 아니다."}],"개념":[{"종류":"표","제목":"중개대상물의 범위","머리":["대상","해당 여부","근거"],"행":[["토지(토지거래허가구역 토지, 가압류된 토지 포함)","해당","제3조제1호"],["건축물·정착물(미등기 건축물, 주벽을 갖춘 신축 중 건물)","해당","제3조제2호"],["입목법상 입목, 공장재단·광업재단","해당","시행령 제2조"],["동·호수가 특정되어 분양계약이 체결된 아파트 분양권","해당","판례"],["입주권(추첨 신청으로 분양예정자가 될 지위), 대토권","비해당","판례"],["영업시설·비품, 거래처·신용·점포 위치의 이점 등 무형의 가치","비해당","판례"],["금전채권(피담보채권 포함)","비해당","판례"]]}],"함정":"넷 모두 해당하지 않는 것을 고르는 문항이라 일부만 고르면 틀린다. 온천수와 미채굴광물은 땅에서 나오는 것이라 토지에 포함된다고 보기 쉽다."},"30회-2차-025":{"한줄":"포상금지급신청서를 받은 등록관청은 수사기관의 처분내용을 조회한 뒤 지급을 결정하고 결정일부터 1월 이내에 지급하므로 ④가 옳다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제28조제2항","원문":"제1항의 규정에 따라 포상금지급신청서를 제출받은 등록관청은 그 사건에 관한 수사기관의 처분내용을 조회한 후 포상금의 지급을 결정하고, 그 결정일부터 1월 이내에 포상금을 지급하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제1항","원문":"법 제46조제1항의 규정에 따른 포상금은 1건당 50만원으로 한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제2항","원문":"제1항의 규정에 따른 포상금은 법 제46조제1항 각 호의 어느 하나에 해당하는 자가 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다."},{"법령":"공인중개사법 시행령","조문":"영 제36조의2제3항","원문":"법 제46조제2항의 규정에 따라 포상금의 지급에 소요되는 비용 중 국고에서 보조할 수 있는 비율은 100분의 50이내로 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제28조제4항","원문":"등록관청은 하나의 사건에 대하여 2건 이상의 신고 또는 고발이 접수된 경우에는 최초로 신고 또는 고발한 자에게 포상금을 지급한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"포상금은 1건당 50만원이다(영 제36조의2제1항)."},{"번호":2,"판정":"틀림","설명":"검사가 공소제기 또는 기소유예의 결정을 한 경우에 포상금을 지급한다(영 제36조의2제2항). 기소유예도 지급 사유다."},{"번호":3,"판정":"틀림","설명":"포상금 지급 비용 중 보조할 수 있는 주체는 국고이고 비율은 100분의 50 이내다(영 제36조의2제3항). 시·도 보조가 아니다."},{"번호":4,"판정":"옳음","설명":"수사기관의 처분내용 조회 후 지급 결정, 결정일부터 1월 이내 지급이다(시행규칙 제28조제2항)."},{"번호":5,"판정":"틀림","설명":"하나의 사건에 2건 이상의 신고·고발이 접수되면 최초로 신고·고발한 자에게 지급한다(시행규칙 제28조제4항). 균등 배분은 2인 이상이 공동으로 신고·고발한 경우다(같은 조 제3항)."}],"개념":[{"종류":"표","제목":"포상금 지급 요건","머리":["구분","내용","조문"],"행":[["신고·고발 대상","무등록 중개업, 거짓·부정한 방법의 개설등록, 중개사무소등록증·공인중개사자격증의 양도·대여·양수·대여받음, 개업공인중개사가 아닌 자의 중개대상물 표시·광고, 제33조제1항제8호·제9호 행위, 제33조제2항의 업무방해","법 제46조제1항"],["지급 요건","행정기관에 발각되기 전에 등록관청·수사기관에 신고·고발하고, 검사가 공소제기 또는 기소유예 결정을 한 경우","영 제36조의2제2항"],["금액","1건당 50만원","영 제36조의2제1항"],["2인 이상 공동 신고·고발","균등 배분(미리 합의하여 신청하면 합의대로)","시행규칙 제28조제3항"],["2건 이상 접수","최초로 신고·고발한 자에게 지급","시행규칙 제28조제4항"],["국고 보조","지급 비용 중 100분의 50 이내","영 제36조의2제3항"]]},{"종류":"흐름","제목":"포상금 지급 절차","단계":[{"이름":"신고·고발","설명":"행정기관에 발각되기 전에 등록관청·수사기관에 신고 또는 고발"},{"이름":"신청","설명":"포상금지급신청서를 등록관청에 제출"},{"이름":"조회","설명":"등록관청이 그 사건에 관한 수사기관의 처분내용을 조회"},{"이름":"지급 결정","설명":"공소제기 또는 기소유예 결정이 있으면 지급 결정"},{"이름":"지급","설명":"결정일부터 1월 이내에 지급(1건당 50만원)"}]}],"함정":"⑤는 균등 배분 규정을 중복 신고에 잘못 붙였다. 균등 배분은 공동 신고·고발일 때이고 따로 접수된 중복 신고는 먼저 한 사람이 받는다. ③은 보조 주체가 시·도가 아니라 국고다."},"30회-2차-023":{"한줄":"공제사업 운용실적은 매 회계연도 종료 후 3개월 이내에 공시해야 하므로 6개월 이내라고 한 ⑤가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제35조","원문":"협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다."},{"법령":"공인중개사법","조문":"법 제42조제2항","원문":"협회는 제1항에 따른 공제사업을 하고자 하는 때에는 공제규정을 제정하여 국토교통부장관의 승인을 얻어야 한다. 공제규정을 변경하고자 하는 때에도 또한 같다."},{"법령":"공인중개사법","조문":"법 제42조의3","원문":"「금융위원회의 설치 등에 관한 법률」에 따른 금융감독원의 원장은 국토교통부장관의 요청이 있는 경우에는 공제사업에 관하여 조사 또는 검사를 할 수 있다."},{"법령":"공인중개사법","조문":"법 제42조제4항","원문":"협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제34조제3호","원문":"책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공제규정을 제정하거나 변경하려면 국토교통부장관의 승인을 얻는다(법 제42조제2항)."},{"번호":2,"판정":"옳음","설명":"금융감독원장은 국토교통부장관의 요청이 있으면 공제사업을 조사하거나 검사할 수 있다(법 제42조의3)."},{"번호":3,"판정":"옳음","설명":"책임준비금을 다른 용도로 사용하려면 국토교통부장관의 승인을 얻는다(법 제42조제4항)."},{"번호":4,"판정":"옳음","설명":"책임준비금 적립비율은 공제사고 발생률과 공제금 지급액 등을 고려하되 공제료 수입액의 100분의 10 이상이다(영 제34조제3호)."},{"번호":5,"판정":"틀림","설명":"운용실적은 매 회계연도 종료 후 3개월 이내에 공시한다(영 제35조). 6개월이 아니다."}],"개념":[{"종류":"표","제목":"공제사업 규정 정리","머리":["항목","내용","조문"],"행":[["공제규정","제정·변경 시 국토교통부장관의 승인","법 제42조제2항"],["회계","다른 회계와 구분하여 별도 회계로 관리","법 제42조제4항"],["책임준비금","다른 용도로 사용하려면 국토교통부장관의 승인","법 제42조제4항"],["책임준비금 적립비율","공제료 수입액의 100분의 10 이상","영 제34조제3호"],["운용실적 공시","매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회 홈페이지에 게시","영 제35조"],["조사·검사","국토교통부장관의 요청이 있으면 금융감독원장이 조사·검사","법 제42조의3"],["운영위원회","위원 19명 이내, 임기 2년에 1회 연임 가능","법 제42조의2제2항, 영 제35조의2제3항"],["재무건전성","지급여력비율 100분의 100 이상 유지","영 제35조의3제1항제1호"]]},{"종류":"흐름","제목":"공제사업 운영 절차","단계":[{"이름":"공제규정 제정","설명":"협회가 공제규정을 제정하거나 변경하려면 국토교통부장관의 승인(법 제42조제2항)"},{"이름":"운영","설명":"공제사업을 별도 회계로 관리, 책임준비금을 공제료 수입액의 100분의 10 이상 적립(법 제42조제4항, 영 제34조제3호)"},{"이름":"감독","설명":"운영위원회가 심의·감독하고, 국토교통부장관의 요청으로 금융감독원장이 조사·검사(법 제42조의2, 제42조의3)"},{"이름":"공시","설명":"매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 홈페이지에 게시(영 제35조)"}]}],"함정":"⑤는 공시 기한을 6개월로 늘려 놓았다. 기한은 3개월이다. ④의 100분의 10은 하한이고 책임준비금 적립비율은 그 이상으로 정한다.","개정":"협회 명칭이 한국공인중개사협회로 정비되었다(법 제41조제1항, 개정 2026.2.27). ①, ③, ⑤는 이 명칭으로 고쳐 실었고 판단은 달라지지 않는다."},"30회-2차-020":{"한줄":"둘 이상의 중개사무소를 둔 경우는 법 제38조제2항제2호의 임의적 취소 사유라 절대적(필요적) 취소 사유가 아니므로 ⑤가 정답이다.","근거":[{"법령":"공인중개사법","조문":"법 제38조제2항제2호","원문":"제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제1호","원문":"개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제7호","원문":"업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제2호","원문":"거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우"},{"법령":"공인중개사법","조문":"법 제38조제1항제3호","원문":"제10조제1항제2호부터 제6호까지 또는 같은 항 제11호ㆍ제12호에 따른 결격사유에 해당하게 된 경우. 다만, 같은 항 제12호에 따른 결격사유에 해당하는 경우로서 그 사유가 발생한 날부터 2개월 이내에 그 사유를 해소한 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법인이 해산하면 등록을 취소해야 한다(법 제38조제1항제1호). 절대적 취소 사유다."},{"번호":2,"판정":"옳음","설명":"자격정지 중인 소속공인중개사에게 중개업무를 하게 한 경우는 절대적 취소 사유다(법 제38조제1항제7호)."},{"번호":3,"판정":"옳음","설명":"거짓이나 그 밖의 부정한 방법으로 개설등록을 한 경우는 절대적 취소 사유다(법 제38조제1항제2호)."},{"번호":4,"판정":"옳음","설명":"법인이 아닌 개업공인중개사가 파산선고를 받고 복권되지 않은 경우는 결격사유(제10조제1항제3호)라 등록을 취소해야 한다(제38조제1항제3호)."},{"번호":5,"판정":"틀림","설명":"둘 이상의 중개사무소를 둔 경우는 임의적 취소 사유다(법 제38조제2항제2호). 이중등록(제1항제4호)과 구별한다."}],"개념":[{"종류":"표","제목":"중개사무소 개설등록 취소 사유","머리":["구분","사유","조문"],"행":[["필요적 취소","개인인 개업공인중개사의 사망, 법인의 해산","법 제38조제1항제1호"],["필요적 취소","거짓이나 그 밖의 부정한 방법으로 개설등록","제1항제2호"],["필요적 취소","결격사유 해당(제10조제1항제2호~제6호, 제11호, 제12호)","제1항제3호"],["필요적 취소","이중등록","제1항제4호"],["필요적 취소","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우","제1항제5호"],["필요적 취소","중개보조원 고용 상한(개업공인중개사와 소속공인중개사 합산 수의 5배) 초과","제1항제5호의2"],["필요적 취소","자기의 성명·상호를 사용하여 중개업무를 하게 하거나 등록증을 양도·대여","제1항제6호"],["필요적 취소","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 함","제1항제7호"],["필요적 취소","최근 1년 이내 2회 이상 업무정지처분을 받고 다시 업무정지 해당 행위","제1항제8호"],["임의적 취소","등록기준 미달, 둘 이상의 중개사무소, 임시 중개시설물, 겸업 위반","법 제38조제2항제1호~제4호"],["임의적 취소","6개월 초과 휴업, 정보 비공개 위반, 거래계약서 거짓 기재, 손해배상 보장조치 미이행, 금지행위","제2항제5호~제9호"],["임의적 취소","최근 1년 이내 3회 이상 업무정지 또는 과태료 처분을 받고 다시 업무정지 또는 과태료 처분 해당 행위(제1항제8호 해당 제외)","제2항제10호"],["임의적 취소","사업자단체 또는 구성원이 공정거래법 위반으로 최근 2년 이내 2회 이상 처분","제2항제11호"]]},{"종류":"표","제목":"최근 1년 이내 처분 횟수와 제재","머리":["받은 처분","다시 한 행위","제재","조문"],"행":[["업무정지 2회 이상","업무정지 해당 행위","등록취소(필요적)","법 제38조제1항제8호"],["업무정지 또는 과태료 3회 이상(위 경우 제외)","업무정지 또는 과태료 해당 행위","등록취소(임의적)","법 제38조제2항제10호"],["업무정지 또는 과태료 2회 이상","과태료 해당 행위","업무정지(임의적, 6개월)","법 제39조제1항제12호, 시행규칙 별표 4"]]}],"함정":"이중등록(제12조 위반, 필요적 취소)과 둘 이상의 중개사무소 설치(제13조 위반, 임의적 취소)는 이름이 비슷하다. 두 사무소를 두면 취소할 수 있을 뿐이다. 임시 중개시설물 설치, 겸업 위반도 같은 임의적 취소 사유다."},"30회-2차-024":{"한줄":"시·도지사는 자격취소처분을 한 때 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보해야 하므로 ②가 옳다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제29조제3항","원문":"시ㆍ도지사는 공인중개사의 자격취소처분을 한 때에는 5일 이내에 이를 국토교통부장관과 다른 시ㆍ도지사에게 통보해야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제29조제1항","원문":"법 제35조의 규정에 따른 공인중개사의 자격취소처분 및 법 제36조의 규정에 따른 자격정지처분은 그 공인중개사자격증(이하 \"자격증\"이라 한다)을 교부한 시ㆍ도지사가 행한다."},{"법령":"공인중개사법","조문":"법 제35조제2항","원문":"시ㆍ도지사는 제1항에 따라 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제21조","원문":"법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법","조문":"법 제35조제4항","원문":"분실 등의 사유로 인하여 제3항에 따라 공인중개사자격증을 반납할 수 없는 자는 제3항에도 불구하고 자격증 반납을 대신하여 그 이유를 기재한 사유서를 시ㆍ도지사에게 제출하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"자격취소처분은 자격증을 교부한 시·도지사가 한다(영 제29조제1항). 현주소지 시장·군수·구청장이 아니다."},{"번호":2,"판정":"옳음","설명":"자격취소처분을 한 때에는 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보한다(영 제29조제3항)."},{"번호":3,"판정":"틀림","설명":"자격을 취소하려면 청문을 실시해야 한다(법 제35조제2항). 생략할 수 없다."},{"번호":4,"판정":"틀림","설명":"자격증은 자격증을 교부한 시·도지사에게 처분을 받은 날부터 7일 이내에 반납한다(시행규칙 제21조). 한국산업인력공단이 아니다."},{"번호":5,"판정":"틀림","설명":"분실 등으로 반납할 수 없으면 반납을 대신하여 그 이유를 적은 사유서를 시·도지사에게 제출한다(법 제35조제4항). 재발급받아 반납하는 절차가 없다."}],"개념":[{"종류":"표","제목":"공인중개사 자격취소 사유(법 제35조제1항)","머리":["호","사유"],"행":[["1","부정한 방법으로 공인중개사의 자격을 취득한 경우"],["2","다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도·대여한 경우"],["3","자격정지처분을 받고 그 정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인인 개업공인중개사의 사원·임원이 되는 경우 포함)"],["4","이 법 또는 공인중개사의 직무와 관련하여 형법 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예 포함)을 선고받은 경우"]]},{"종류":"흐름","제목":"자격취소 절차","단계":[{"이름":"청문","설명":"시·도지사가 자격을 취소하려면 청문을 실시(법 제35조제2항)"},{"이름":"처분","설명":"자격증을 교부한 시·도지사가 처분. 사무소 소재지 시·도지사와 다르면 사무소 소재지 시·도지사가 절차를 모두 이행한 후 교부한 시·도지사에게 통보(영 제29조제1항·제2항)"},{"이름":"통보","설명":"취소처분을 한 때 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보(영 제29조제3항)"},{"이름":"반납","설명":"처분을 받은 날부터 7일 이내에 자격증을 교부한 시·도지사에게 반납. 분실 등이면 사유서 제출(시행규칙 제21조, 법 제35조제4항)"},{"이름":"미반납 제재","설명":"반납·사유서 제출 의무 위반 시 100만원 이하 과태료(법 제51조제3항제6호), 시·도지사가 부과"}]}],"함정":"③은 청문이 필수라는 점을, ④는 반납 상대(교부한 시·도지사)를 놓치면 옳게 보인다. ⑤는 분실한 경우 사유서 제출로 반납을 갈음한다.","개정":"시·도지사의 자격취소 통보는 5일 이내에 국토교통부장관과 다른 시·도지사에게 통보하는 것으로 정해져 있다(영 제29조제3항, 개정 2023.11.16). ②는 문구를 현행 통보로 맞춰 실었고 판단은 달라지지 않는다."},"30회-2차-026":{"한줄":"공제업무 개선명령 불이행의 과태료는 400만원으로 휴업 재개 미신고(20만원), 이전신고 미이행(30만원), 등록증 미게시(30만원), 휴업기간 변경 미신고(20만원)보다 크다.","근거":[{"법령":"공인중개사법","조문":"법 제51조제2항제8호","원문":"제42조의4에 따른 공제업무의 개선명령을 이행하지 아니한 자"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 차목","원문":"법 제42조의4에 따른 공제업무의 개선명령을 이행하지 않은 경우: 과태료 400만원"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 더목","원문":"법 제21조제1항을 위반하여 휴업, 폐업, 휴업한 중개업의 재개 또는 휴업기간의 변경 신고를 하지 않은 경우: 과태료 20만원"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 너목","원문":"법 제20조제1항을 위반하여 중개사무소의 이전신고를 하지 않은 경우: 과태료 30만원"},{"법령":"공인중개사법 시행령","조문":"영 별표 2 파목","원문":"법 제17조를 위반하여 중개사무소등록증 등을 게시하지 않은 경우: 과태료 30만원"}],"선지":[{"번호":1,"판정":"-","설명":"400만원. 다섯 가운데 가장 큰 금액이다."},{"번호":2,"판정":"-","설명":"20만원. 휴업한 중개업의 재개 신고를 하지 않은 경우다."},{"번호":3,"판정":"-","설명":"30만원. 중개사무소 이전신고를 하지 않은 경우다."},{"번호":4,"판정":"-","설명":"30만원. 중개사무소등록증을 게시하지 않은 경우다."},{"번호":5,"판정":"-","설명":"20만원. 휴업기간의 변경 신고를 하지 않은 경우다. 재개 신고 위반과 금액이 같다."}],"개념":[{"종류":"표","제목":"과태료 금액(영 별표 2)","머리":["위반행위","과태료"],"행":[["공제업무 개선명령 불이행","400만원"],["임원 징계·해임 요구·시정명령 불이행","400만원"],["부동산거래정보망 운영규정 위반","400만원"],["공제사업 운용실적 미공시","300만원"],["확인·설명 불성실 또는 근거자료 미제시","250만원 또는 500만원"],["연수교육 미이수","위반 기간별 20만원~100만원"],["사무소 명칭 위반, 등록증 미반납","50만원"],["등록증 미게시, 이전신고, 손해배상 설명 위반, 자격증 미반납","30만원"],["휴업·폐업·재개·휴업기간 변경 미신고","20만원"]]},{"종류":"표","제목":"과태료 부과·징수권자(법 제51조제5항)","머리":["부과권자","과태료 사유","조문"],"행":[["국토교통부장관","인터넷 광고 모니터링 자료 제출·조치 요구 불이행, 부동산거래정보망 운영규정 위반, 거래정보사업자의 보고·검사 거부, 공제사업 운용실적 미공시, 공제 개선명령 불이행, 임원 징계·해임 요구 불이행, 협회 조사·검사 거부","제2항제1호의2·제1호의3·제1호의5·제6호~제8호·제8호의2·제9호"],["시·도지사","연수교육 미이수, 공인중개사자격증 미반납·사유서 미제출","제2항제5호의2, 제3항제6호"],["등록관청","부당 표시·광고, 중개보조원 신분 미고지, 확인·설명 불성실, 등록증 미게시, 사무소 명칭 위반, 표시·광고 위반, 이전신고·휴업·폐업·재개·휴업기간 변경 미신고, 손해배상책임 설명·증서 교부 위반, 등록증 미반납","제2항제1호·제1호의4·제1호의6, 제3항제1호~제5호·제7호"]]}],"함정":"금액이 큰 쪽은 국토교통부장관이 부과하는 협회·공제 관련 과태료(300만원~400만원)이고, 중개사무소 관련 신고·게시 의무는 20만원~50만원 수준이다. 신고 위반 중에서도 이전신고(30만원)는 휴업·폐업·재개·변경 신고(20만원)보다 크다.","개정":"협회 명칭이 한국공인중개사협회로 정비되었다(법 제41조제1항, 개정 2026.2.27). 금액은 달라지지 않았다."},"30회-2차-003":{"한줄":"시험시행기관장은 시험에서 부정한 행위를 한 응시자의 시험을 무효로 하고 처분일부터 5년간 응시자격을 정지하므로 ④가 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제4조의3","원문":"제4조제1항 및 제2항에 따라 시험을 시행하는 시ㆍ도지사 또는 국토교통부장관(이하 \"시험시행기관장\"이라 한다)은 시험에서 부정한 행위를 한 응시자에 대하여는 그 시험을 무효로 하고, 그 처분이 있은 날부터 5년간 시험응시자격을 정지한다. 이 경우 시험시행기관장은 지체 없이 이를 다른 시험시행기관장에게 통보하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제3조","원문":"국토교통부장관이 법 제4조제2항에 따라 직접 시험문제를 출제하거나 시험을 시행하려는 경우에는 심의위원회의 의결을 미리 거쳐야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제3조제2항","원문":"법 제5조제3항의 규정에 따라 공인중개사자격증의 재교부를 신청하는 자는 별지 제4호서식의 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법","조문":"법 제5조제2항","원문":"시ㆍ도지사는 제1항에 따른 합격자에게 국토교통부령으로 정하는 바에 따라 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법 시행령","조문":"영 제7조제2항","원문":"시험시행기관장은 법 제4조에 따라 시험을 시행하려는 때에는 예정 시험일시ㆍ시험방법 등 시험시행에 관한 개략적인 사항을 매년 2월 말일까지 「신문 등의 진흥에 관한 법률」 제2조제1호가목에 따른 일반일간신문(이하 \"일간신문\"이라 한다), 관보, 방송 중 하나 이상에 공고하고, 인터넷 홈페이지 등에도 이를 공고해야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국토교통부장관이 직접 시험문제를 출제하거나 시험을 시행하려면 심의위원회의 의결을 미리 거쳐야 한다(영 제3조)."},{"번호":2,"판정":"틀림","설명":"재교부신청서는 자격증을 교부한 시·도지사에게 제출한다(시행규칙 제3조제2항). 국토교통부장관이 아니다."},{"번호":3,"판정":"틀림","설명":"자격증은 시·도지사가 합격자에게 교부한다(법 제5조제2항). 국토교통부장관이 교부하지 않는다."},{"번호":4,"판정":"옳음","설명":"부정한 행위를 한 응시자는 시험이 무효가 되고 그 처분일부터 5년간 응시자격이 정지된다(법 제4조의3)."},{"번호":5,"판정":"틀림","설명":"시험 개략 공고는 매년 2월 말일까지 일간신문, 관보, 방송 중 하나 이상에 하고 인터넷 홈페이지에도 공고한다(영 제7조제2항). 전년도 12월 31일, 관보 및 일간신문 모두가 아니다."}],"개념":[{"종류":"표","제목":"자격시험·자격증 규정","머리":["항목","내용","조문"],"행":[["시험 시행","시·도지사가 시행. 국토교통부장관이 직접 출제·시행하려면 심의위원회 의결을 미리 거침","법 제4조, 영 제3조"],["시험 미시행","부득이한 사정이 있으면 심의위원회 의결을 거쳐 당해연도 시험을 시행하지 않을 수 있음","영 제7조제1항"],["시행 공고","예정 시험일시·방법 등 개략적 사항을 매년 2월 말일까지 일간신문·관보·방송 중 하나 이상에 공고하고 인터넷 홈페이지에도 공고","영 제7조제2항"],["세부 공고","시험일시·장소·방법 등을 시험시행일 90일 전까지 공고","영 제7조제3항"],["부정행위자","시험 무효, 처분일부터 5년간 응시자격 정지","법 제4조의3"],["자격증 교부","시·도지사가 합격자 결정 공고일부터 1개월 이내에 자격증교부대장 기재 후 교부","법 제5조제2항, 시행규칙 제3조제1항"],["자격증 재교부","자격증을 교부한 시·도지사에게 신청","법 제5조제3항, 시행규칙 제3조제2항"],["자격 결격","자격취소 후 3년이 지나지 않은 자는 공인중개사가 될 수 없음","법 제6조"],["자격증 대여 등 금지","성명 사용 허락, 자격증 양도·대여, 양수·대여받음, 알선 금지","법 제7조"]]},{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","① 공인중개사의 시험 등 자격취득, ② 부동산 중개업의 육성, ③ 중개보수 변경, ④ 손해배상책임의 보장 등","법 제2조의2제1항제1호~제4호"],["시·도지사 구속력","심의사항 중 제1호(시험 등 자격취득)에 한해 시·도지사가 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","위원장 제외 위원 2년(보궐위원은 전임자 잔여기간)","영 제1조의2제3항"],["제척","위원이 안건에 증언·진술·자문·조사·연구·용역·감정을 한 경우 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정(대상 위원은 참여 불가)","영 제1조의3제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"]]}],"함정":"⑤의 공고 시한과 매체가 함정이다. 시한은 매년 2월 말일이고 매체는 일간신문·관보·방송 중 하나 이상이다(홈페이지 공고도 함께). 자격증 교부와 재교부는 모두 시·도지사 사무다(②, ③)."},"30회-2차-008":{"한줄":"위원장이 부득이한 사유로 직무를 수행할 수 없을 때는 위원장이 미리 지명한 위원이 대행하며 부위원장 제도가 없으므로 ④가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제1조의4제2항","원문":"위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다."},{"법령":"공인중개사법","조문":"법 제2조의2제1항","원문":"공인중개사의 업무에 관한 다음 각 호의 사항을 심의하기 위하여 국토교통부에 공인중개사 정책심의위원회를 둘 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의2제1항","원문":"「공인중개사법」(이하 \"법\"이라 한다) 제2조의2제1항에 따른 공인중개사 정책심의위원회(이하 \"심의위원회\"라 한다)는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"영 제1조의3제1항제3호","원문":"위원이 해당 안건에 대하여 증언, 진술, 자문, 조사, 연구, 용역 또는 감정을 한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제1조의5제2항","원문":"심의위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"국토교통부에 심의위원회를 둘 수 있다(법 제2조의2제1항)."},{"번호":2,"판정":"옳음","설명":"심의위원회는 위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다(영 제1조의2제1항)."},{"번호":3,"판정":"옳음","설명":"위원이 해당 안건에 대하여 자문을 한 경우 심의·의결에서 제척된다(영 제1조의3제1항제3호)."},{"번호":4,"판정":"틀림","설명":"위원장이 직무를 수행할 수 없을 때는 위원장이 미리 지명한 위원이 대행한다(영 제1조의4제2항). 부위원장이 대행하는 것이 아니다."},{"번호":5,"판정":"옳음","설명":"재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다(영 제1조의5제2항)."}],"개념":[{"종류":"표","제목":"공인중개사 정책심의위원회","머리":["항목","내용","조문"],"행":[["설치","국토교통부에 둘 수 있음","법 제2조의2제1항"],["심의사항","① 공인중개사의 시험 등 자격취득, ② 부동산 중개업의 육성, ③ 중개보수 변경, ④ 손해배상책임의 보장 등","법 제2조의2제1항제1호~제4호"],["시·도지사 구속력","심의사항 중 제1호(시험 등 자격취득)에 한해 시·도지사가 따라야 함","법 제2조의2제3항"],["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","위원장 제외 위원 2년(보궐위원은 전임자 잔여기간)","영 제1조의2제3항"],["제척","위원이 안건에 증언·진술·자문·조사·연구·용역·감정을 한 경우 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정(대상 위원은 참여 불가)","영 제1조의3제2항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["회의","재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결","영 제1조의5제2항"]]}],"함정":"직무 대행자를 부위원장으로 쓰는 것은 다른 위원회의 일반적인 구조에서 온 착각이다. 이 위원회는 부위원장을 두지 않고 위원장이 미리 지명한 위원이 대행한다. 공제사업 운영위원회는 반대로 위원장·부위원장을 호선하고 부위원장이 대행한다(영 제35조의2제6항)."},"30회-2차-002":{"한줄":"이 법 위반 벌금형이 결격이 되는 금액은 300만원 이상이라서 200만원 벌금형은 결격사유에 해당하지 않는다.","근거":[{"법령":"공인중개사법","조문":"법 제10조제1항제11호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제4호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 금고 이상의 실형의 선고를 받고 그 집행이 종료(집행이 종료된 것으로 보는 경우를 포함한다)되거나 집행이 면제된 날부터 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제6호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제35조제1항에 따라 공인중개사의 자격이 취소된 후 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제10호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제39조에 따라 업무정지처분을 받은 개업공인중개사인 법인의 업무정지의 사유가 발생한 당시의 사원 또는 임원이었던 자로서 해당 개업공인중개사에 대한 업무정지기간이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"법 제10조제1항제7호","원문":"다음 각 호의 어느 하나에 해당하는 자는 중개사무소의 개설등록을 할 수 없다. 제36조제1항에 따라 공인중개사의 자격이 정지된 자로서 자격정지기간중에 있는 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"이 법 위반 벌금형은 300만원 이상이어야 결격이다. 200만원은 해당하지 않는다(법 제10조제1항제11호)."},{"번호":2,"판정":"옳음","설명":"금고 이상의 실형은 집행 종료·면제일부터 3년이 지나지 않으면 결격이다(법 제10조제1항제4호)."},{"번호":3,"판정":"옳음","설명":"자격이 취소된 후 3년이 지나지 않으면 결격이다(법 제10조제1항제6호)."},{"번호":4,"판정":"옳음","설명":"업무정지처분을 받은 법인의 정지 사유 발생 당시 사원·임원이었던 자는 법인의 업무정지기간이 지나기 전까지 결격이다(법 제10조제1항제10호)."},{"번호":5,"판정":"옳음","설명":"자격정지기간 중에 있는 자는 결격이다(법 제10조제1항제7호)."}],"개념":[{"종류":"표","제목":"결격 기간 비교(법 제10조제1항)","머리":["사유","기산 시점","기간"],"행":[["금고 이상의 실형(제4호)","집행 종료·집행 면제일","3년"],["금고 이상의 집행유예(제5호)","유예기간 만료일","2년(유예기간 중 포함)"],["이 법 위반 300만원 이상 벌금형(제11호)","선고일","3년"],["공인중개사 자격취소(제6호)","취소일","3년"],["개설등록 취소(제8호)","취소일","3년(법 제40조제3항 취소는 폐업기간 공제)"],["자격정지(제7호)","-","자격정지기간 중"],["업무정지 후 폐업(제9호)","-","업무정지기간이 지나기 전"]]},{"종류":"표","제목":"결격자의 범위와 제재(법 제10조, 제38조, 제39조)","머리":["구분","내용","근거"],"행":[["개설등록 불가","제10조제1항 제1호~제12호","법 제10조제1항"],["소속공인중개사·중개보조원 불가","제10조제1항 제1호~제11호(법인에 관한 제12호 제외)","법 제10조제2항"],["결격자를 고용한 개업공인중개사","업무정지 가능. 사유 발생일부터 2개월 이내 해소하면 제외","법 제39조제1항제1호"],["등록 후 결격 발생","등록 취소. 제12호(법인)는 사유 발생일부터 2개월 이내 해소하면 제외","법 제38조제1항제3호"]]}],"함정":"이 법 위반 벌금형은 300만원 이상이 기준이다(①의 200만원은 미달). 나머지는 실형·자격취소 후 3년, 법인의 업무정지 당시 사원·임원, 자격정지기간 중이라는 열거 사유 그대로다."},"30회-2차-018":{"한줄":"분사무소설치신고확인서 재교부 신청, 개설등록 신청, 분사무소 설치 신고는 조례 수수료 대상이고, 국토교통부장관이 시행하는 시험은 아니다.","근거":[{"법령":"공인중개사법","조문":"법 제47조제1항","원문":"다음 각 호의 어느 하나에 해당하는 자는 해당 지방자치단체의 조례로 정하는 바에 따라 수수료를 납부하여야 한다. 다만, 공인중개사자격시험을 제4조제2항의 규정에 따라 국토교통부장관이 시행하는 경우 제1호에 해당하는 자는 국토교통부장관이 결정ㆍ공고하는 수수료를 납부하여야 한다. 1. 제4조에 따른 공인중개사자격시험에 응시하는 자 2. 제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자 3. 제9조제1항에 따라 중개사무소의 개설등록을 신청하는 자 4. 제11조제2항에 따라 중개사무소등록증의 재교부를 신청하는 자 5. 제13조제3항에 따라 분사무소설치의 신고를 하는 자 6. 제13조제5항에 따라 분사무소설치신고확인서의 재교부를 신청하는 자"},{"법령":"공인중개사법","조문":"법 제47조제2항","원문":"제4조에 따른 공인중개사자격시험 또는 제5조제3항에 따른 공인중개사자격증 재교부업무를 제45조의 규정에 따라 위탁한 경우에는 해당 업무를 위탁받은 자가 위탁한 자의 승인을 얻어 결정ㆍ공고하는 수수료를 각각 납부하여야 한다."},{"법령":"공인중개사법","조문":"법 제13조제5항","원문":"제5조제3항은 제4항에 따른 신고확인서의 재교부에 관하여 이를 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니고 ㄷ, ㄹ이 빠졌다."},{"번호":2,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니고 ㄷ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄷ, ㄹ이 조례로 정한 수수료를 내는 경우다."},{"번호":4,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니고 ㄱ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄴ은 조례 수수료 대상이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"분사무소설치신고확인서의 재교부를 신청하는 자는 수수료를 낸다(법 제47조제1항제6호)."},{"기호":"ㄴ","판정":"틀림","설명":"국토교통부장관이 시행하는 시험의 응시자는 조례가 아니라 장관이 결정·공고하는 수수료를 낸다(법 제47조제1항 단서)."},{"기호":"ㄷ","판정":"옳음","설명":"개설등록을 신청하는 자는 수수료를 낸다(법 제47조제1항제3호)."},{"기호":"ㄹ","판정":"옳음","설명":"분사무소 설치 신고를 하는 자는 수수료를 낸다(법 제47조제1항제5호)."}],"개념":[{"종류":"표","제목":"수수료 납부 대상(법 제47조제1항)","머리":["호","납부 대상","수수료 결정"],"행":[["1","공인중개사자격시험 응시","지방자치단체 조례(국토교통부장관이 시행하는 시험은 장관이 결정·공고)"],["2","공인중개사자격증 재교부 신청","조례"],["3","중개사무소 개설등록 신청","조례"],["4","중개사무소등록증 재교부 신청","조례"],["5","분사무소 설치 신고","조례"],["6","분사무소설치신고확인서 재교부 신청","조례"]]},{"종류":"표","제목":"응시수수료의 반환(영 제8조제2항, 시행규칙 제2조제2항)","머리":["사유","반환액"],"행":[["수수료를 과오납한 경우","과오납한 금액 전부"],["시험시행기관의 귀책사유로 응시하지 못한 경우","납입 수수료 전부"],["응시원서 접수기간 내 접수 취소","납입 수수료 전부"],["접수마감일 다음 날부터 7일 이내 접수 취소","납입 수수료의 100분의 60"],["그 이후 시험시행일 10일 전까지 접수 취소","납입 수수료의 100분의 50"]]}],"함정":"자격시험 응시수수료는 시험을 국토교통부장관이 시행하면 장관이 결정·공고하는 수수료를 낸다. 이 경우는 조례 수수료가 아니다(ㄴ).","개정":"보기 ㄱ의 \"분사무소설치신고필증\"은 현행 법령의 용어인 \"분사무소설치신고확인서\"로 고쳐 실었다(법 제13조제4항·제5항, 제47조제1항제6호)."},"30회-2차-005":{"한줄":"법 제13조는 중개사무소를 두는 지역만 정할 뿐이고 관할구역 밖에 있는 중개대상물의 중개를 막는 조문은 없어 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제13조제1항","원문":"개업공인중개사는 그 등록관청의 관할 구역안에 중개사무소를 두되, 1개의 중개사무소만을 둘 수 있다."},{"법령":"공인중개사법","조문":"법 제13조제2항","원문":"개업공인중개사는 천막 그 밖에 이동이 용이한 임시 중개시설물을 설치하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제13조제3항","원문":"제1항에도 불구하고 법인인 개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다."},{"법령":"공인중개사법","조문":"법 제9조제1항","원문":"중개업을 영위하려는 자는 국토교통부령으로 정하는 바에 따라 중개사무소(법인의 경우에는 주된 중개사무소를 말한다)를 두려는 지역을 관할하는 시장(구가 설치되지 아니한 시의 시장과 특별자치도 행정시의 시장을 말한다. 이하 같다)ㆍ군수 또는 구청장(이하 \"등록관청\"이라 한다)에게 중개사무소의 개설등록을 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사는 등록관청의 관할구역 안에 1개의 중개사무소만 둘 수 있다(법 제13조제1항)."},{"번호":2,"판정":"옳음","설명":"천막 그 밖에 이동이 용이한 임시 중개시설물은 설치할 수 없다(법 제13조제2항)."},{"번호":3,"판정":"옳음","설명":"분사무소는 법인인 개업공인중개사만 둘 수 있다(법 제13조제3항)."},{"번호":4,"판정":"틀림","설명":"사무소의 설치 지역을 정한 조문(법 제13조제1항)과 달리 중개대상물의 소재지를 관할구역으로 제한하는 조문은 없다."},{"번호":5,"판정":"옳음","설명":"법인은 신고하고 관할 구역 외의 지역에 분사무소를 둘 수 있다(법 제13조제3항)."}],"개념":[{"종류":"표","제목":"중개사무소의 설치(법 제13조)","머리":["항목","내용","위반 시"],"행":[["개수","등록관청 관할구역 안에 1개만","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제4호), 등록취소 가능"],["임시 시설물","천막 등 이동이 용이한 임시 중개시설물 설치 금지","제49조제1항제5호, 등록취소 가능(제38조제2항제3호)"],["분사무소","법인인 개업공인중개사만 신고하고 관할 구역 밖에 설치","-"],["공동 사용","다른 개업공인중개사와 공동 사용 가능. 업무정지기간 중 일정한 경우 제한","-"],["중개 지역","사무소를 두는 지역만 정하고 중개대상물의 소재지는 제한하지 않음","-"]]},{"종류":"표","제목":"분사무소 설치(법 제13조제3항, 영 제15조)","머리":["항목","내용","근거"],"행":[["설치 주체","법인인 개업공인중개사","법 제13조제3항"],["설치 지역","주된 사무소 소재지가 속한 시·군·구를 제외한 시·군·구, 시·군·구별 1개소","영 제15조제1항"],["책임자","공인중개사. 다른 법률에 따라 중개업을 하는 법인의 분사무소는 예외","영 제15조제2항"],["신고처","주된 사무소 소재지 관할 등록관청","영 제15조제3항"],["첨부서류","책임자 실무교육 수료확인증 사본, 보증 설정 증명서류, 사용권 확보 증명서류","영 제15조제3항제3호~제5호"],["신고확인서","적합하면 신고확인서를 교부하고 설치예정지역 관할 시장·군수·구청장에게 통보","법 제13조제4항"],["보증","분사무소마다 2억원 이상 추가 설정","영 제24조제1항제1호"]]}],"함정":"제한되는 것은 사무소를 두는 장소다. 중개 대상 부동산의 소재지는 등록관청 관할과 무관하다."},"30회-2차-007":{"한줄":"소속공인중개사의 미등록 인장 사용은 시·도지사의 자격정지 사유이고, 업무정지는 개업공인중개사 대상이며 범위도 6개월이므로 ②가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제36조제1항제2호","원문":"시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"},{"법령":"공인중개사법","조문":"법 제39조제1항제2호","원문":"등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 업무의 정지를 명할 수 있다. 이 경우 법인인 개업공인중개사에 대하여는 법인 또는 분사무소별로 업무의 정지를 명할 수 있다. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제2항","원문":"제1항의 규정에 따라 등록한 인장을 변경한 경우에는 개업공인중개사 및 소속공인중개사는 변경일부터 7일 이내에 그 변경된 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제4항","원문":"법인인 개업공인중개사의 제1항 및 제2항에 따른 인장 등록은 「상업등기규칙」에 따른 인감증명서의 제출로 갈음한다."},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 제9조제6항","원문":"제1항에 따른 인장의 등록은 다음 각 호의 신청이나 신고와 같이 할 수 있다. 1. 제4조에 따른 중개사무소 개설등록신청 2. 제8조에 따른 소속공인중개사ㆍ중개보조원에 대한 고용 신고"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인인 개업공인중개사의 인장 등록은 인감증명서 제출로 갈음한다(시행규칙 제9조제4항)."},{"번호":2,"판정":"틀림","설명":"소속공인중개사가 등록하지 않은 인장을 사용하면 시·도지사가 6개월의 범위에서 자격을 정지할 수 있다(법 제36조제1항제2호). 업무정지는 개업공인중개사에 대한 처분이고 기간도 6개월의 범위다(법 제39조제1항)."},{"번호":3,"판정":"옳음","설명":"인장 등록은 개설등록 신청과 같이 할 수 있다(시행규칙 제9조제6항제1호)."},{"번호":4,"판정":"옳음","설명":"소속공인중개사 고용 신고와 같이 인장을 등록할 수 있다(시행규칙 제9조제6항제2호)."},{"번호":5,"판정":"옳음","설명":"등록한 인장을 변경하면 변경일부터 7일 이내에 등록한다(시행규칙 제9조제2항)."}],"개념":[{"종류":"표","제목":"인장등록(법 제16조, 시행규칙 제9조)","머리":["항목","내용","근거"],"행":[["등록 대상자","개업공인중개사, 소속공인중개사","법 제16조제1항"],["등록 시기","업무를 개시하기 전","시행규칙 제9조제1항"],["변경 등록","변경일부터 7일 이내","시행규칙 제9조제2항"],["사용 의무","중개행위를 할 때 등록한 인장 사용","법 제16조제2항"],["함께 할 수 있는 신청","개설등록 신청, 소속공인중개사·중개보조원 고용 신고와 같이 등록 가능","시행규칙 제9조제6항"],["위반 제재","개업공인중개사는 업무정지, 소속공인중개사는 자격정지","법 제39조제1항제2호, 제36조제1항제2호"]]},{"종류":"비교","제목":"자격정지와 업무정지","왼쪽":{"이름":"자격정지(소속공인중개사)","항목":["처분권자: 시·도지사(법 제36조제1항)","대상: 소속공인중개사로 업무를 수행하는 공인중개사","기간: 6개월의 범위","인장등록 위반도 사유(제1항제2호)"]},"오른쪽":{"이름":"업무정지(개업공인중개사)","항목":["처분권자: 등록관청(법 제39조제1항)","대상: 개업공인중개사(법인은 법인 또는 분사무소별)","기간: 6개월의 범위","사유 발생일부터 3년이 지나면 처분 불가(제3항)","인장등록 위반도 사유(제1항제2호)"]}}],"함정":"소속공인중개사의 인장 위반에는 업무정지가 아니라 자격정지가 붙는다. 처분권자도 등록관청이 아니라 시·도지사다. 기간의 상한은 어느 쪽이나 6개월이다."},"30회-2차-011":{"한줄":"표시·광고에는 중개사무소의 명칭·연락처와 개업공인중개사의 성명을 명시하고, 소속공인중개사의 성명은 명시 사항이 아니다.","근거":[{"법령":"공인중개사법","조문":"법 제18조의2제1항","원문":"개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고(「표시ㆍ광고의 공정화에 관한 법률」 제2조에 따른 표시ㆍ광고를 말한다. 이하 같다)를 하려면 중개사무소, 개업공인중개사에 관한 사항으로서 대통령령으로 정하는 사항을 명시하여야 하며, 중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"영 제17조의2제1항","원문":"법 제18조의2제1항에서 \"대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다. 1. 중개사무소의 명칭, 소재지, 연락처 및 등록번호 2. 개업공인중개사의 성명(법인인 경우에는 대표자의 성명)"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄹ도 명시 사항이라 ㄱ, ㄴ만으로는 모자란다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 명시 사항이 아니다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 명시 사항이 아니고 ㄱ, ㄴ이 빠졌다."},{"번호":4,"판정":"옳음","설명":"연락처(ㄱ), 명칭(ㄴ), 개업공인중개사의 성명(ㄹ)이 명시 사항이다."},{"번호":5,"판정":"틀림","설명":"ㄷ은 명시 사항이 아니고 ㄴ이 빠졌다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"중개사무소의 연락처는 명시 사항이다(영 제17조의2제1항제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"중개사무소의 명칭은 명시 사항이다(영 제17조의2제1항제1호)."},{"기호":"ㄷ","판정":"틀림","설명":"소속공인중개사의 성명은 영 제17조의2제1항에 열거되어 있지 않다."},{"기호":"ㄹ","판정":"옳음","설명":"개업공인중개사의 성명(법인은 대표자)은 명시 사항이다(영 제17조의2제1항제2호)."}],"개념":[{"종류":"표","제목":"중개대상물 표시·광고 명시 사항(법 제18조의2제1항·제2항, 영 제17조의2)","머리":["구분","명시 사항"],"행":[["모든 표시·광고","중개사무소의 명칭, 소재지, 연락처, 등록번호, 개업공인중개사의 성명(법인은 대표자)"],["금지","중개보조원에 관한 사항은 명시 금지"],["인터넷 표시·광고 추가","소재지, 면적, 가격, 중개대상물 종류, 거래 형태"],["건축물 등 추가","총 층수, 사용승인·사용검사·준공검사 등을 받은 날"],["건축물 등 추가","방향, 방의 개수, 욕실의 개수, 입주가능일, 주차대수, 관리비"],["구체적 방법","국토교통부장관이 고시(영 제17조의2제3항)"]]},{"종류":"표","제목":"중개사무소 명칭과 표시·광고(법 제18조, 제18조의2)","머리":["항목","내용","근거"],"행":[["명칭","개업공인중개사는 사무소 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\" 사용","법 제18조제1항"],["명칭 금지","개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 유사 명칭 사용 금지","법 제18조제2항"],["옥외광고물","설치하는 경우 등록증에 표기된 개업공인중개사 성명 표기(법인은 대표자, 분사무소는 신고확인서의 책임자). 설치 자체는 의무 아님","법 제18조제3항, 시행규칙 제10조의2"],["철거","위반 간판은 등록관청이 철거를 명하고 이행하지 않으면 행정대집행","법 제18조제5항"],["표시·광고 명시","중개사무소 명칭·소재지·연락처·등록번호, 개업공인중개사 성명(법인은 대표자). 중개보조원 사항은 명시 금지","법 제18조의2제1항, 영 제17조의2제1항"],["표시·광고 주체","개업공인중개사가 아닌 자는 중개대상물 표시·광고 금지","법 제18조의2제3항"],["제재","명칭 미사용·성명 미표기 100만원 이하 과태료, 명칭 무자격 사용 1년 이하 징역 또는 1천만원 이하 벌금","법 제51조제3항제2호, 제49조제1항제6호"]]}],"함정":"명시 사항은 사무소 명칭·소재지·연락처·등록번호와 개업공인중개사 성명이다. 중개보조원에 관한 사항은 명시하면 안 되고, 소속공인중개사의 성명은 열거되어 있지 않다."},"30회-2차-015":{"한줄":"신고서 서식의 폐업 칸은 \"폐업일\"이고 폐업기간 칸은 없으므로 ②가 틀리다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다. 1. 3개월을 초과하여 휴업(법 제9조에 따른 중개사무소 개설등록 후 업무를 개시하지 않는 경우를 포함한다. 이하 이 조에서 같다)하려는 경우 2. 폐업하려는 경우 3. 3개월을 초과하여 휴업한 부동산중개업을 재개하려는 경우 4. 신고한 휴업기간을 변경하려는 경우"},{"법령":"공인중개사법 시행규칙","조문":"시행규칙 별지 제13호서식","원문":"개업공인중개사 종별: [ ] 법인 [ ] 공인중개사 [ ] 법 제7638호 부칙 제6조제2항에 따른 개업공인중개사 / 신고사항: 휴업(휴업기간), 폐업(폐업일), 재개(재개일), 휴업기간 변경(원래 휴업기간, 변경 휴업기간) / 첨부서류: 중개사무소등록증(휴업신고 또는 폐업신고의 경우에만 첨부하며, 법인의 분사무소인 경우에는 분사무소설치 신고확인서를 첨부합니다)"},{"법령":"공인중개사법","조문":"법 제21조의2제1항제2호","원문":"개업공인중개사는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 사무소의 간판을 철거하여야 한다. 제21조제1항에 따라 등록관청에 폐업사실을 신고한 경우"},{"법령":"공인중개사법 시행령","조문":"영 제18조제6항제3호","원문":"법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. 취학"}],"선지":[{"번호":1,"판정":"옳음","설명":"서식의 종별 칸은 법인, 공인중개사, 법 제7638호 부칙 제6조제2항에 따른 개업공인중개사로 나뉜다(별지 제13호서식)."},{"번호":2,"판정":"틀림","설명":"서식에는 휴업은 휴업기간, 폐업은 폐업일을 적는다(별지 제13호서식). 폐업기간을 적는 칸은 없다."},{"번호":3,"판정":"옳음","설명":"개설등록 후 업무를 개시하지 않는 경우도 3개월을 초과하면 휴업이므로 등록증을 첨부해 미리 신고한다(영 제18조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"폐업사실을 신고하면 지체 없이 간판을 철거한다(법 제21조의2제1항제2호)."},{"번호":5,"판정":"옳음","설명":"취학은 6개월을 초과하여 휴업할 수 있는 사유다(영 제18조제6항제3호)."}],"개념":[{"종류":"표","제목":"휴업·폐업·재개·휴업기간 변경 신고서(시행규칙 별지 제13호서식)","머리":["항목","기재 내용"],"행":[["신고서 종류","부동산중개업 또는 분사무소의 휴업, 폐업, 재개, 휴업기간 변경"],["개업공인중개사 종별","법인, 공인중개사, 법 제7638호 부칙 제6조제2항에 따른 개업공인중개사"],["휴업","휴업기간"],["폐업","폐업일"],["재개","재개일"],["휴업기간 변경","원래 휴업기간, 변경 휴업기간"],["첨부서류","중개사무소등록증(휴업·폐업 신고만, 분사무소는 분사무소설치 신고확인서)"],["처리기간","즉시"]]},{"종류":"흐름","제목":"휴업·재개·폐업 신고","단계":[{"이름":"휴업 신고","설명":"3개월을 초과하는 휴업은 등록관청에 미리 신고하고 등록증을 첨부(영 제18조제1항제1호)"},{"이름":"휴업 기간","설명":"6개월을 초과할 수 없음. 질병 요양, 징집 입영, 취학, 임신·출산 등은 예외(법 제21조제2항, 영 제18조제6항)"},{"이름":"기간 변경","설명":"신고한 휴업기간을 바꾸려면 미리 신고. 전자문서 신고 가능(영 제18조제1항제4호)"},{"이름":"재개 신고","설명":"3개월을 초과하여 휴업한 중개업을 재개하려면 미리 신고. 등록관청은 반납받은 등록증을 즉시 반환(영 제18조제1항제3호·제5항)"},{"이름":"폐업 신고","설명":"폐업하려면 미리 신고하고 등록증 첨부. 신고 후 간판은 지체 없이 철거(영 제18조제1항제2호, 법 제21조의2제1항)"}]}],"함정":"휴업은 기간이 있고 폐업은 시점(폐업일)이다. 서식 하나로 휴업·폐업·재개·기간 변경을 모두 신고하며 등록증은 휴업·폐업 때만 붙인다."},"30회-2차-010":{"한줄":"고용관계 종료 신고는 종료일부터 10일 이내에 하므로 14일 이내라고 한 ②가 틀리다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제4항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원과의 고용관계가 종료된 때에는 법 제15조제1항에 따라 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다."},{"법령":"공인중개사법","조문":"법 제15조제2항","원문":"소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법","조문":"법 제30조제1항","원문":"개업공인중개사는 중개행위를 하는 경우 고의 또는 과실로 인하여 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다."},{"법령":"민법","조문":"민법 제750조","원문":"고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다."},{"법령":"공인중개사법 시행규칙","조문":"규칙 제10조제3호","원문":"3. 개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당되는 자가 있는 경우로 한정한다)"},{"법령":"공인중개사법 시행규칙","조문":"규칙 제8조제1항","원문":"업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개보조원의 업무상 행위는 고용한 개업공인중개사의 행위로 본다(법 제15조제2항)."},{"번호":2,"판정":"틀림","설명":"종료 신고는 종료된 날부터 10일 이내다(규칙 제8조제4항). 14일이 아니다."},{"번호":3,"판정":"옳음","설명":"개업공인중개사는 법 제30조제1항에 따라 책임을 지고, 중개보조원 본인도 과실로 손해를 입히면 민법 제750조의 불법행위책임을 진다는 것이 판례의 입장이다."},{"번호":4,"판정":"옳음","설명":"소속공인중개사를 둔 경우 개업공인중개사와 소속공인중개사의 자격증 원본을 사무소에 게시한다(규칙 제10조제3호)."},{"번호":5,"판정":"옳음","설명":"중개보조원 고용 신고도 전자문서로 할 수 있다(규칙 제8조제1항)."}],"개념":[{"종류":"표","제목":"소속공인중개사와 중개보조원 비교","머리":["구분","소속공인중개사","중개보조원"],"행":[["정의","개업공인중개사에 소속된 공인중개사로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자(법 제2조제5호)","공인중개사가 아닌 자로서 현장안내·일반서무 등 단순한 업무를 보조하는 자(법 제2조제6호)"],["고용 신고","업무개시 전까지 등록관청에 신고, 전자문서 신고 포함(규칙 제8조제1항)","업무개시 전까지 등록관청에 신고, 전자문서 신고 포함(규칙 제8조제1항)"],["고용 전 교육","신고일 전 1년 이내 시·도지사의 실무교육(법 제34조제2항)","신고일 전 1년 이내 시·도지사 또는 등록관청의 직무교육(법 제34조제3항)"],["자격 확인","등록관청이 자격증을 발급한 시·도지사에게 자격 확인 요청(규칙 제8조제2항)","해당 없음(공인중개사가 아님)"],["고용관계 종료 신고","종료일부터 10일 이내(규칙 제8조제4항)","종료일부터 10일 이내(규칙 제8조제4항)"],["인장등록","등록 대상(법 제16조제1항)","등록 대상 아님"],["업무상 행위","고용한 개업공인중개사의 행위로 봄(법 제15조제2항)","고용한 개업공인중개사의 행위로 봄(법 제15조제2항)"]]},{"종류":"비교","제목":"고용인의 행위에 대한 책임","왼쪽":{"이름":"개업공인중개사","항목":["중개행위로 고의·과실에 의한 재산상 손해를 입히면 배상책임(법 제30조제1항)","고용인의 업무상 행위는 자신의 행위로 봄(법 제15조제2항)","업무개시 전 보증보험·공제 가입 또는 공탁(법 제30조제3항)"]},"오른쪽":{"이름":"중개보조원","항목":["자신의 과실로 거래당사자에게 손해를 입히면 민법 제750조의 불법행위책임이 별도로 성립(판례)","인장등록 대상 아님(법 제16조제1항)","고용관계 종료 신고는 종료일부터 10일 이내(규칙 제8조제4항)"]}}],"함정":"③은 고용한 개업공인중개사만 책임진다고 알고 있으면 틀린 보기로 읽힌다. 개업공인중개사의 책임과 별개로 중개보조원 본인의 불법행위책임도 성립한다. 정답은 종료 신고 기한(10일)을 14일로 바꾼 ②다."},"30회-2차-017":{"한줄":"임대차의 전속중개계약에서 공개해야 하는 정보는 ㄹ(환경 조건)뿐이다. 권리자의 인적 사항은 공개하면 안 되고, 임대차의 공시지가는 공개하지 않을 수 있다.","근거":[{"법령":"공인중개사법 시행령","조문":"영 제20조제2항제4호","원문":"4. 도로 및 대중교통수단과의 연계성, 시장ㆍ학교 등과의 근접성, 지형 등 입지조건, 일조(日照)ㆍ소음ㆍ진동 등 환경조건"},{"법령":"공인중개사법 시행령","조문":"영 제20조제2항제5호","원문":"5. 소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항. 다만, 각 권리자의 주소ㆍ성명 등 인적 사항에 관한 정보는 공개하여서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"영 제20조제2항제7호","원문":"7. 중개대상물의 거래예정금액 및 공시지가. 다만, 임대차의 경우에는 공시지가를 공개하지 아니할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄹ만 공개해야 하는 정보이므로 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄱ(임차인 성명)과 ㄴ(저당권자 주소)은 권리자의 인적 사항이라 공개하면 안 된다."},{"번호":3,"판정":"틀림","설명":"ㄷ 공시지가는 임대차이므로 공개하지 않을 수 있는 정보다."},{"번호":4,"판정":"틀림","설명":"ㄱ, ㄴ은 공개 금지 정보라 ㄱ, ㄴ, ㄹ을 고른 조합은 맞지 않는다."},{"번호":5,"판정":"틀림","설명":"ㄱ, ㄴ은 공개 금지 정보이고 ㄷ은 임대차에서 공개 의무가 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"기존 임차인의 성명은 권리자의 인적 사항이므로 공개하여서는 아니 된다(영 제20조제2항제5호 단서)."},{"기호":"ㄴ","판정":"틀림","설명":"저당권자의 주소는 권리자의 인적 사항이므로 공개하여서는 아니 된다(영 제20조제2항제5호 단서)."},{"기호":"ㄷ","판정":"틀림","설명":"임대차의 경우 공시지가는 공개하지 않을 수 있어 반드시 공개할 정보가 아니다(영 제20조제2항제7호 단서)."},{"기호":"ㄹ","판정":"옳음","설명":"일조·소음·진동 등 환경조건은 공개 정보다(영 제20조제2항제4호)."}],"개념":[{"종류":"표","제목":"전속중개계약 공개 정보(영 제20조제2항)","머리":["호","공개 정보","비고"],"행":[["1","중개대상물의 종류, 소재지, 지목 및 면적, 건축물의 용도·구조 및 건축연도 등 특정 사항",""],["2","벽면 및 도배의 상태",""],["3","수도·전기·가스·소방·열공급·승강기 설비, 오수·폐수·쓰레기 처리시설 등의 상태",""],["4","도로 및 대중교통수단과의 연계성, 시장·학교 등과의 근접성, 지형 등 입지조건, 일조·소음·진동 등 환경조건",""],["5","소유권·전세권·저당권·지상권 및 임차권 등 권리관계","각 권리자의 주소·성명 등 인적 사항은 공개 금지"],["6","공법상의 이용제한 및 거래규제에 관한 사항",""],["7","중개대상물의 거래예정금액 및 공시지가","임대차는 공시지가를 공개하지 않을 수 있음"]]}],"함정":"ㄷ은 공시지가가 공개 대상 목록에 있어서 고르기 쉽다. 임대차라는 조건이 붙으면 공개 의무가 없어진다. 권리관계는 공개하되 권리자의 인적 사항만 빼야 한다."},"30회-2차-014":{"한줄":"개업공인중개사가 중개의뢰인과 직접 거래를 하는 행위는 법 제33조제1항제6호가 금지하므로 ③이 옳다.","근거":[{"법령":"공인중개사법","조문":"법 제33조제1항","원문":"개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다."},{"법령":"공인중개사법","조문":"법 제33조제1항제6호","원문":"6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법","조문":"법 제10조제3항","원문":"개업공인중개사ㆍ소속공인중개사ㆍ중개보조원 및 개업공인중개사인 법인의 사원ㆍ임원(이하 \"개업공인중개사등\"이라 한다)"},{"법령":"공인중개사법","조문":"법 제33조제1항제1호","원문":"1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"금지행위의 적용 대상인 개업공인중개사등에는 법인의 사원·임원이 들어가므로 사원의 매매업도 금지된다(법 제10조제3항, 제33조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"거래당사자 쌍방을 대리하는 행위는 금지된다(법 제33조제1항제6호)."},{"번호":3,"판정":"옳음","설명":"중개의뢰인과 직접 거래를 하는 행위는 금지된다(법 제33조제1항제6호)."},{"번호":4,"판정":"틀림","설명":"법인의 임원도 개업공인중개사등이어서 직접 거래가 금지된다(법 제10조제3항, 제33조제1항제6호)."},{"번호":5,"판정":"틀림","설명":"중개보조원도 개업공인중개사등이어서 직접 거래가 금지된다(법 제10조제3항, 제33조제1항제6호)."}],"개념":[{"종류":"표","제목":"금지행위 규정이 적용되는 사람","머리":["규정","적용 대상","비고"],"행":[["법 제33조제1항","개업공인중개사등","개업공인중개사·소속공인중개사·중개보조원·개업공인중개사인 법인의 사원·임원(법 제10조제3항)"],["법 제33조제2항","누구든지","시세에 부당한 영향을 줄 목적으로 개업공인중개사등의 업무를 방해하는 행위"],["법 제18조의2제3항","개업공인중개사가 아닌 자","중개대상물에 대한 표시·광고 금지"]]},{"종류":"표","제목":"개업공인중개사등의 금지행위(법 제33조제1항)와 벌칙","머리":["호","금지행위","벌칙"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["2","중개사무소 개설등록 없이 중개업을 하는 자인 사실을 알면서 그를 통해 중개를 의뢰받거나 그에게 자기 명의를 이용하게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["3","사례·증여 그 밖의 어떤 명목으로도 법정 보수 또는 실비를 초과하여 금품을 받는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["4","중개대상물의 거래상 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["5","관계 법령에서 양도·알선 등이 금지된 부동산의 분양·임대 등과 관련 있는 증서 등의 매매·교환 등을 중개하거나 그 매매를 업으로 하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["6","중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["7","탈세 등 관계 법령을 위반할 목적으로 미등기·전매제한 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["8","부당한 이익을 얻거나 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 시세에 부당한 영향을 주거나 줄 우려가 있는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["9","단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"]]}],"함정":"제33조제1항은 개업공인중개사만이 아니라 소속공인중개사, 중개보조원, 법인의 사원·임원까지 적용된다. 선지 ①④⑤는 이 범위를 좁혀 금지되지 않는다고 적었다."},"30회-2차-016":{"한줄":"공제사업을 하는 자도 계약금등의 예치명의자가 될 수 있으므로 그 명의로 예치하도록 권고할 수 없다고 한 ④가 틀리다.","근거":[{"법령":"공인중개사법","조문":"법 제31조제1항","원문":"개업공인중개사는 거래의 안전을 보장하기 위하여 필요하다고 인정하는 경우에는 거래계약의 이행이 완료될 때까지 계약금ㆍ중도금 또는 잔금(이하 이 조에서 \"계약금등\"이라 한다)을 개업공인중개사 또는 대통령령으로 정하는 자의 명의로 금융기관, 제42조에 따라 공제사업을 하는 자 또는 「자본시장과 금융투자업에 관한 법률」에 따른 신탁업자 등에 예치하도록 거래당사자에게 권고할 수 있다."},{"법령":"공인중개사법 시행령","조문":"영 제27조제1항제2호","원문":"2. 「보험업법」에 따른 보험회사"},{"법령":"공인중개사법 시행령","조문":"영 제27조제1항제5호","원문":"5. 법 제42조의 규정에 따라 공제사업을 하는 자"},{"법령":"공인중개사법 시행령","조문":"영 제27조제3항","원문":"개업공인중개사는 제2항의 규정에 따라 거래계약과 관련된 계약금등을 자기 명의로 금융기관 등에 예치하는 경우에는 자기 소유의 예치금과 분리하여 관리될 수 있도록 하여야 하며"}],"선지":[{"번호":1,"판정":"옳음","설명":"거래의 안전을 위해 필요하다고 인정하면 예치를 권고할 수 있다(법 제31조제1항)."},{"번호":2,"판정":"옳음","설명":"예치 대상은 계약금·중도금 또는 잔금이다(법 제31조제1항)."},{"번호":3,"판정":"옳음","설명":"보험업법에 따른 보험회사는 예치명의자가 될 수 있다(영 제27조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"법 제42조에 따라 공제사업을 하는 자도 예치명의자다(영 제27조제1항제5호). 그 명의로 예치하도록 권고할 수 있다."},{"번호":5,"판정":"옳음","설명":"자기 명의로 예치하는 경우 자기 소유의 예치금과 분리하여 관리해야 한다(영 제27조제3항)."}],"개념":[{"종류":"표","제목":"계약금등 예치(법 제31조, 영 제27조)","머리":["항목","내용"],"행":[["권고","개업공인중개사는 거래의 안전을 위해 필요하다고 인정하면 예치를 권고할 수 있다(의무 아님)"],["예치 대상","계약금·중도금 또는 잔금"],["예치명의자","개업공인중개사, 은행, 보험회사, 신탁업자, 체신관서, 공제사업을 하는 자, 거래계약 이행 보장 업무를 수행하는 전문회사"],["자기 명의 예치 시","자기 소유의 예치금과 분리하여 관리, 거래당사자의 동의 없이 인출 금지, 예치 금액을 보장하는 보증보험·공제 가입 또는 공탁"],["미리 수령","예치 후 매도인 등은 계약 해제 시 반환을 보장하는 금융기관·보증보험회사 발행 보증서를 교부하고 계약금등을 미리 수령할 수 있다(법 제31조제2항)"]]}],"함정":"예치명의자 목록(개업공인중개사, 은행, 보험회사, 신탁업자, 체신관서, 공제사업자, 전문회사)에서 공제사업을 하는 자가 빠졌다고 적은 것이 ④다. 예치는 권고일 뿐 의무가 아니다."},"30회-2차-032":{"한줄":"정정신청 대상인 개업공인중개사 사항은 전화번호·상호·사무소 소재지이고, 성명·주소는 포함되지 않는다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항","원문":"① 거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 다음 각 호의 어느 하나에 해당하는 사항이 잘못 기재된 경우에는 신고관청에 신고 내용의 정정을 신청할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제1호","원문":"1. 거래당사자의 주소ㆍ전화번호 또는 휴대전화번호"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제2호","원문":"2. 거래 지분 비율"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제3호","원문":"3. 개업공인중개사의 전화번호ㆍ상호 또는 사무소 소재지"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제4호","원문":"4. 거래대상 건축물의 종류"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제3조제1항제5호","원문":"5. 거래대상 부동산등(부동산을 취득할 수 있는 권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다. 이하 같다)의 지목, 면적, 거래 지분 및 대지권비율"}],"선지":[{"번호":1,"판정":"-","설명":"거래대상 건축물의 종류는 정정신청 사항이다(규칙 제3조제1항제4호)."},{"번호":2,"판정":"-","설명":"개업공인중개사 성명·주소는 정정신청 사항이 아니다. 개업공인중개사는 전화번호·상호·사무소 소재지만 정정한다(규칙 제3조제1항제3호)."},{"번호":3,"판정":"-","설명":"거래대상 부동산등의 면적은 정정신청 사항이다(규칙 제3조제1항제5호)."},{"번호":4,"판정":"-","설명":"거래 지분 비율은 정정신청 사항이다(규칙 제3조제1항제2호). 지분 비율 변경은 변경신고 사항이기도 하다(제3항제1호)."},{"번호":5,"판정":"-","설명":"거래당사자의 전화번호는 정정신청 사항이다(규칙 제3조제1항제1호)."}],"개념":[{"종류":"표","제목":"정정신청 사항(규칙 제3조제1항)","머리":["호","정정 대상"],"행":[["1","거래당사자의 주소·전화번호 또는 휴대전화번호"],["2","거래 지분 비율"],["3","개업공인중개사의 전화번호·상호 또는 사무소 소재지"],["4","거래대상 건축물의 종류"],["5","거래대상 부동산등의 지목, 면적, 거래 지분 및 대지권비율"]]},{"종류":"비교","제목":"정정신청과 변경신고(규칙 제3조)","왼쪽":{"이름":"정정신청(제1항·제2항)","항목":["신고 내용이 잘못 기재된 경우","거래당사자 또는 개업공인중개사가 신청","신고필증에 정정사항을 표시하고 서명 또는 날인하여 제출","거래당사자 주소·전화번호 정정은 일방이 단독으로 신청 가능"]},"오른쪽":{"이름":"변경신고(제3항·제4항)","항목":["신고 후 내용이 바뀐 경우","부동산등기법에 따른 등기신청 전에 신고","별지 제3호서식 부동산거래계약 변경 신고서 제출","면적 변경 없이 거래가격만 바뀌면 거래계약서 사본 등 증명서류 첨부"]}}],"함정":"개업공인중개사 인적사항은 신고사항이다. 정정 대상은 전화번호·상호·사무소 소재지로 좁고, 성명·주소는 정정 신청 목록에 없다."},"30회-2차-039":{"한줄":"택지개발촉진법에 따라 공급된 토지의 임대차계약은 매매·공급계약·지위의 매매 어디에도 속하지 않아 신고 대상이 아니다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항제1호","원문":"1. 부동산의 매매계약"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항제2호","원문":"2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항제3호나목","원문":"나. 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획의 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가로 취득한 입주자로 선정된 지위"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제3조제3항","원문":"3. 「도시개발법」 … 7. 「택지개발촉진법」"}],"선지":[{"번호":1,"판정":"-","설명":"주택법에 따라 공급된 주택을 사고파는 매매계약은 부동산의 매매계약이다(법 제3조제1항제1호)."},{"번호":2,"판정":"-","설명":"토지의 임대차계약은 신고 대상 계약이 아니다. 신고 대상은 매매계약, 공급계약, 지위의 매매계약이다(법 제3조제1항)."},{"번호":3,"판정":"-","설명":"도시개발법에 따른 부동산 공급계약은 신고 대상이다(법 제3조제1항제2호, 영 제3조제3항제3호)."},{"번호":4,"판정":"-","설명":"등록된 체육시설이 있는 건물도 건축물이므로 그 매매계약은 신고 대상이다(법 제3조제1항제1호)."},{"번호":5,"판정":"-","설명":"관리처분계획 인가로 취득한 입주자로 선정된 지위의 매매계약은 신고 대상이다(법 제3조제1항제3호나목)."}],"개념":[{"종류":"표","제목":"부동산 거래신고 대상 계약(법 제3조제1항, 영 제3조제3항)","머리":["구분","대상","근거"],"행":[["매매","부동산(토지·건축물)의 매매계약","법 제3조제1항제1호"],["공급계약","건축물의 분양에 관한 법률, 공공주택 특별법, 도시개발법, 도시 및 주거환경정비법, 빈집 및 소규모주택 정비에 관한 특례법, 산업입지 및 개발에 관한 법률, 주택법, 택지개발촉진법에 따른 공급계약","법 제3조제1항제2호, 영 제3조제3항"],["지위의 매매","공급계약으로 부동산을 공급받는 자로 선정된 지위(분양권)의 매매계약","법 제3조제1항제3호가목"],["지위의 매매","관리처분계획 인가(도시 및 주거환경정비법) 또는 사업시행계획인가(빈집 및 소규모주택 정비에 관한 특례법)로 취득한 입주자로 선정된 지위(입주권)의 매매계약","법 제3조제1항제3호나목"],["대상 아님","위 각 호에 없는 계약(증여, 임대차 등). 주택 임대차는 별도의 임대차 신고 제도(법 제6조의2)","법 제3조제1항"]]},{"종류":"표","제목":"공급계약 신고 대상 법률(영 제3조제3항)","머리":["호","법률"],"행":[["1","건축물의 분양에 관한 법률"],["2","공공주택 특별법"],["3","도시개발법"],["4","도시 및 주거환경정비법"],["4의2","빈집 및 소규모주택 정비에 관한 특례법"],["5","산업입지 및 개발에 관한 법률"],["6","주택법"],["7","택지개발촉진법"]]}],"함정":"택지개발촉진법은 공급계약의 근거 법률 목록에 들어 있어 ②도 신고 대상처럼 보인다. ②는 공급계약이 아니라 임대차계약이다."},"30회-2차-040":{"한줄":"계약의 조건이나 기한이 있으면 그 조건 또는 기한이 신고사항이다(영 별표 1 제1호바목).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 별표 1 제1호바목","원문":"바. 계약의 조건이나 기한이 있는 경우에는 그 조건 또는 기한"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제3조제1항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제3조제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다. … 2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"규칙 제5조제2항","원문":"② 제2조제4항, 제3조제2항ㆍ제4항 및 제4조제1항ㆍ제2항의 개업공인중개사의 위임을 받은 소속공인중개사(「공인중개사법」 제2조제5호에 따른 소속공인중개사를 말한다. 이하 같다)는 부동산거래계약 신고서 등의 제출을 대행할 수 있다. 이 경우 소속공인중개사는 신분증명서를 신고관청에 보여줘야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"거래신고 기한은 계약 체결일부터 30일이다(법 제3조제1항). 60일이 아니다."},{"번호":2,"판정":"틀림","설명":"신고 의무자는 거래당사자 또는 개업공인중개사다. 소속공인중개사는 개업공인중개사의 위임을 받아 제출을 대행할 수 있을 뿐이고, 중개보조원에 관한 규정은 없다(법 제3조, 규칙 제5조제2항)."},{"번호":3,"판정":"틀림","설명":"지방공사는 국가등이다. 국가등이 한쪽 당사자이면 국가등이 신고한다(법 제3조제1항 단서, 영 제3조제2항제2호)."},{"번호":4,"판정":"틀림","설명":"공법상의 거래규제 및 이용제한은 영 별표 1 신고사항이 아니다."},{"번호":5,"판정":"옳음","설명":"조건·기한은 신고사항이다(영 별표 1 제1호바목)."}],"개념":[{"종류":"표","제목":"신고사항 구성(영 제3조제1항, 별표 1)","머리":["구분","신고사항"],"행":[["공통(제1호)","거래당사자 인적사항, 계약 체결일·중도금 및 잔금 지급일, 소재지·지번·지목·면적, 부동산 종류, 실제 거래가격, 조건·기한, 매수인이 국내 주소·거소가 없을 때 위탁관리인, 외국인 매수인의 체류자격 등, 개업공인중개사 인적사항과 사무소 상호·전화번호·소재지"],["법인의 주택 거래(제2호)","법인 등기 현황, 거래상대방과의 관계, 취득 목적, 자금조달계획, 이용계획"],["주택 매수(제3호·제3호의2)","자금조달계획과 지급방식, 매수자 본인의 입주 여부·시기 등 이용계획"],["토지 매수(제4호·제5호)","자금조달계획, 토지 이용계획"]]},{"종류":"표","제목":"신고 주체와 방법(법 제3조)","머리":["상황","신고 주체·방법","근거"],"행":[["거래당사자 직접거래","거래당사자가 공동으로 신고. 계약 체결일부터 30일 이내","법 제3조제1항"],["일방이 국가등","국가등이 신고하고 서명 또는 날인도 국가등이 단독으로 한다","법 제3조제1항 단서, 규칙 제2조제2항"],["국가등의 범위","국가, 지방자치단체, 공공기관, 지방직영기업·지방공사·지방공단","법 제3조제1항 단서, 영 제3조제2항"],["개업공인중개사가 거래계약서를 작성·교부","개업공인중개사가 신고. 공동중개이면 공동으로 신고","법 제3조제3항"],["일방이 신고 거부","다른 일방이 단독 신고. 거래계약서 사본, 계약금 지급 확인 서류, 단독신고사유서 첨부","법 제3조제2항·제4항, 규칙 제2조제3항"],["소속공인중개사","개업공인중개사의 위임을 받아 제출을 대행하고 신분증명서를 보여준다","규칙 제5조제2항"]]}],"함정":"소속공인중개사는 제출 대행이 가능하다는 점이 신고 의무자라는 말로 옮겨지면 ②처럼 틀린다. ③의 지방공사는 국가등이어서 공동신고 대상이 아니다."},"30회-2차-027":{"한줄":"특별자치시장은 외국인등의 취득·계속보유 신고내용을 매 분기 종료일부터 1개월 이내에 국토교통부장관에게 직접 제출한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제5조제3항","원문":"③ 신고관청은 법 제8조에 따른 신고내용을 매 분기 종료일부터 1개월 이내에 특별시장ㆍ광역시장ㆍ도지사 또는 특별자치도지사에게 제출(「전자서명법」 제2조제1호에 따른 전자문서에 의한 제출을 포함한다)하여야 한다. 다만, 특별자치시장은 직접 국토교통부장관에게 제출하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제5조제2항","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다. … 2. 법원의 확정판결"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제6조제3항","원문":"③ 제1항에 따른 신청서를 받은 신고관청은 신청서를 받은 날부터 다음 각 호의 구분에 따른 기간 안에 허가 또는 불허가 처분을 해야 한다. 다만, 부득이한 사유로 제1호에 따른 기간 안에 허가 또는 불허가 처분을 할 수 없는 경우에는 30일의 범위에서 그 기간을 연장할 수 있으며, 기간을 연장하는 경우에는 연장 사유와 처리예정일을 지체 없이 신청인에게 알려야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제8조제2항","원문":"② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경매로 취득하면 취득한 날부터 6개월 이내에 신고한다(법 제8조제2항). 3개월이 아니다."},{"번호":2,"판정":"틀림","설명":"임대차계약은 부동산등을 취득하는 계약이 아니어서 법 제8조의 신고 대상이 아니다."},{"번호":3,"판정":"옳음","설명":"특별자치시장은 신고내용을 국토교통부장관에게 직접 제출한다(영 제5조제3항 단서)."},{"번호":4,"판정":"틀림","설명":"생태·경관보전지역은 법 제9조제1항제1호의 구역이 아니라서 처리기간이 15일이다(영 제6조제3항제2호). 30일은 군사기지 등 구역·지역이다."},{"번호":5,"판정":"틀림","설명":"법원의 확정판결로 취득한 경우도 계약 외 원인으로서 6개월 이내에 신고한다(영 제5조제2항제2호, 법 제8조제2항)."}],"개념":[{"종류":"표","제목":"신고내용 제출 경로(영 제5조제3항·제4항, 제6조제5항·제6항)","머리":["단계","내용"],"행":[["신고관청","매 분기 종료일부터 1개월 이내 신고내용(허가내용)을 시·도지사에게 제출"],["특별시장·광역시장·도지사·특별자치도지사","제출받은 날부터 1개월 이내 국토교통부장관에게 제출"],["특별자치시장","국토교통부장관에게 직접 제출"]]},{"종류":"표","제목":"외국인등의 토지취득 허가(법 제9조, 영 제6조)","머리":["항목","내용"],"행":[["허가 지역","군사기지 및 군사시설 보호구역 등, 지정문화유산과 보호물·보호구역, 천연기념물등과 보호물·보호구역, 생태·경관보전지역, 야생생물 특별보호구역"],["허가 시기·허가권자","토지취득계약 체결 전에 신고관청의 허가"],["처리기간","군사기지 등 국방목적 구역·지역은 30일, 그 밖의 구역·지역은 15일(부득이하면 군사기지 등은 30일 범위에서 연장)"],["예외","법 제11조에 따른 토지거래계약 허가를 받은 경우"],["위반 효과","허가 없이 체결한 토지취득계약은 효력이 발생하지 않는다(법 제9조제3항)"]]}],"함정":"③은 특별자치시에만 적용되는 예외이고 나머지 시·군·구는 시·도지사를 거친다. ④는 허가 구역에 따라 처리기간이 갈린다는 점이 요점이다.","개정":"외국인등의 토지취득 허가 처리기간은 영 제6조제3항에서 군사기지 등 구역·지역 30일, 그 밖의 구역·지역 15일로 나뉜다(<개정 2023.10.4>). 선지 ④는 생태·경관보전지역으로 한정해 틀린 문장으로 유지했다. 정답 번호는 그대로다."},"30회-2차-028":{"한줄":"매수청구 토지의 매수자는 국가·지방자치단체·한국토지주택공사와 영 제11조제1항제1호~제10호 기관 중에서 지정한다. 지방자치단체·한국석유공사·한국관광공사가 이에 든다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제16조제2항","원문":"② 제1항에 따른 매수 청구를 받은 시장ㆍ군수 또는 구청장은 국가, 지방자치단체, 한국토지주택공사, 그 밖에 대통령령으로 정하는 공공기관 또는 공공단체 중에서 매수할 자를 지정하여, 매수할 자로 하여금 예산의 범위에서 공시지가를 기준으로 하여 해당 토지를 매수하게 하여야 한다. 다만, 토지거래계약 허가신청서에 적힌 가격이 공시지가보다 낮은 경우에는 허가신청서에 적힌 가격으로 매수할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제13조제2항","원문":"② 법 제16조제2항에서 \"대통령령으로 정하는 공공기관 또는 공공단체\"란 제11조제1항제1호부터 제10호까지의 기관 또는 단체를 말한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제11조제1항","원문":"4. 「한국관광공사법」에 따른 한국관광공사 … 7. 「한국석유공사법」에 따른 한국석유공사 … 15. 「한국은행법」에 따른 한국은행 … 16. 「지방공기업법」에 따른 지방공사와 지방공단 … 22. 「항만공사법」에 따른 항만공사"}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄴ(한국은행), ㅁ(항만공사)은 제11호~제22호 기관이라 지정 대상이 아니고, ㄱ·ㄹ·ㅂ은 지정 대상이다."},{"번호":2,"판정":"옳음","설명":"지방자치단체(법 제16조제2항), 한국석유공사(영 제11조제1항제7호), 한국관광공사(제4호)가 지정될 수 있다."},{"번호":3,"판정":"틀림","설명":"ㄴ(한국은행), ㄷ(지방공사), ㅁ(항만공사)이 지정 대상이 아니다."},{"번호":4,"판정":"틀림","설명":"ㅁ(항만공사)은 지정 대상이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄴ, ㄷ, ㅁ은 지정 대상이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"지방자치단체는 법 제16조제2항이 직접 규정한 매수자다."},{"기호":"ㄴ","판정":"틀림","설명":"한국은행은 영 제11조제1항제15호라서 영 제13조제2항의 지정 대상(제1호~제10호)이 아니다."},{"기호":"ㄷ","판정":"틀림","설명":"지방공사는 영 제11조제1항제16호라서 지정 대상이 아니다."},{"기호":"ㄹ","판정":"옳음","설명":"한국석유공사는 영 제11조제1항제7호다."},{"기호":"ㅁ","판정":"틀림","설명":"항만공사는 영 제11조제1항제22호라서 지정 대상이 아니다."},{"기호":"ㅂ","판정":"옳음","설명":"한국관광공사는 영 제11조제1항제4호다."}],"개념":[{"종류":"표","제목":"선매자·매수 지정 대상 기관(법 제15조·제16조, 영 제11조제1항·제12조·제13조)","머리":["구분","기관"],"행":[["국가·지방자치단체·한국토지주택공사","법에 직접 규정"],["영 제11조제1항제1호~제10호","한국농수산식품유통공사, 대한석탄공사, 한국토지주택공사, 한국관광공사, 한국농어촌공사, 한국도로공사, 한국석유공사, 한국수자원공사, 한국전력공사, 한국철도공사"],["영 제11조제1항제11호~제22호","산림조합·중앙회, 농협, 수협, 중소벤처기업진흥공단, 한국은행, 지방공사·지방공단, 공무원연금공단, 인천국제공항공사, 국민연금공단, 사립학교교직원연금공단, 한국자산관리공사, 항만공사(국가등 허가 협의 특례에는 해당하나 선매자·매수자 지정 대상에서는 제외)"]]},{"종류":"표","제목":"토지거래계약 허가(법 제11조~제14조)","머리":["항목","내용"],"행":[["허가 대상","허가구역 안 토지의 소유권·지상권(취득을 목적으로 하는 권리 포함)을 대가를 받고 이전·설정하는 계약(예약 포함)"],["허가 절차","당사자 공동 신청. 허가관청은 신청서를 받은 날부터 15일 이내 허가·변경허가·불허가 처분(영 제8조제3항)"],["허가 없이 체결","계약은 효력이 발생하지 않는다(법 제11조제6항)"],["이의신청","처분을 받은 날부터 1개월 이내 시장·군수·구청장에게(법 제13조제1항)"],["매수청구","불허가처분을 통지받은 날부터 1개월 이내(법 제16조제1항)"],["적용 제외","수용, 민사집행법상 경매, 영 제11조제3항의 계약"]]}],"함정":"국가등 허가 협의 특례(법 제14조제1항)는 영 제11조제1항의 22개 기관이 모두 대상이고, 선매자·매수자 지정(영 제12조·제13조)은 제1호~제10호 기관으로 좁다. 한국은행·지방공사·항만공사는 앞 특례에는 들고 뒤 지정에는 들지 않는다."},"30회-2차-030":{"한줄":"이행명령을 받은 자가 명령을 이행해도 그 전에 이미 부과된 이행강제금은 징수해야 한다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제3항","원문":"③ 시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 제2항에 따른 이행강제금을 부과ㆍ징수할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제4항","원문":"④ 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"법 제18조제5항","원문":"⑤ 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에는 새로운 이행강제금의 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제3항제2호","원문":"2. 토지거래계약허가를 받아 토지를 취득한 자가 직접 이용하지 아니하고 임대한 경우: 토지 취득가액의 100분의 7에 상당하는 금액"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"영 제16조제7항","원문":"⑦ 제6항에 따른 이행강제금 부과처분을 받은 자는 법 제18조제6항에 따라 이의를 제기하려는 경우에는 부과처분을 고지받은 날부터 30일 이내에 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"반복 부과의 기준일은 최초의 의무이행 위반이 있었던 날이 아니라 최초의 이행명령이 있었던 날이다(법 제18조제3항)."},{"번호":2,"판정":"틀림","설명":"이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다(법 제18조제4항)."},{"번호":3,"판정":"옳음","설명":"이행명령을 이행해도 이미 부과된 이행강제금은 징수한다(법 제18조제5항)."},{"번호":4,"판정":"틀림","설명":"직접 이용하지 않고 임대한 경우의 이행강제금은 취득가액의 100분의 7이다(영 제16조제3항제2호). 100분의 20이 아니다."},{"번호":5,"판정":"틀림","설명":"부과처분에 이의를 제기하려면 고지받은 날부터 30일 이내에 시장·군수·구청장에게 한다(법 제18조제6항, 영 제16조제7항). 국토교통부장관이나 14일이 아니다."}],"개념":[{"종류":"표","제목":"이행강제금 금액(법 제18조제2항, 영 제16조제3항)","머리":["위반 유형","금액(토지 취득가액 기준)"],"행":[["당초 목적대로 이용하지 않고 방치","100분의 10"],["직접 이용하지 않고 임대","100분의 7"],["허가관청의 승인 없이 이용목적 변경","100분의 5"],["위 세 가지에 해당하지 않는 경우","100분의 7"]]},{"종류":"흐름","제목":"이행명령과 이행강제금(법 제18조, 영 제16조)","단계":[{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내로 정한다(영 제16조제1항)"},{"이름":"계고","설명":"이행기간 내 이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 계고(영 제16조제5항)"},{"이름":"부과","설명":"이행명령이 이행되지 않으면 이행강제금 부과. 최초 이행명령이 있었던 날을 기준으로 1년에 한 번씩 반복 부과(법 제18조제3항)"},{"이름":"이의제기","설명":"부과처분을 고지받은 날부터 30일 이내 시장·군수·구청장에게(영 제16조제7항, 법 제18조제6항)"},{"이름":"이행 시","설명":"새로운 이행강제금 부과는 즉시 중지, 이미 부과된 이행강제금은 징수(법 제18조제5항). 의무기간이 지나면 부과 불가(제4항)"}]}],"함정":"임대의 이행강제금 비율(100분의 7)과 방치의 비율(100분의 10)을 서로 바꾸어 놓기 쉽다. ⑤는 기한 30일, 이의제기 상대방이 시장·군수·구청장이다."},"30회-2차-031":{"한줄":"무허가건물이라도 건물의 요건을 갖추면 관습법상 법정지상권이 성립하고(ㄱ), 성립 후 증축해도 구 건물을 기준으로 인정되므로(ㄴ) ㄱ, ㄴ이 옳다.","근거":[{"판례":"대법원 판례(관습법상 법정지상권의 성립)","요지":"동일인 소유이던 토지와 건물 중 건물만 매매 등으로 소유자가 달라지고 철거 특약이 없으면 건물 소유자는 관습법상 법정지상권을 취득한다. 건물이 무허가이거나 미등기여도 성립한다."},{"판례":"대법원 판례(건물의 증축·개축)","요지":"관습법상 법정지상권이 성립한 뒤 건물을 증축·개축·신축해도 구 건물을 기준으로 지상권이 인정된다. 그 범위는 구 건물의 유지·사용에 필요한 범위로 한정된다."},{"판례":"대법원 판례(법정지상권의 포기)","요지":"건물 취득 시 건물 소유자가 대지 소유자와 대지에 대한 임대차계약을 체결했다면 관습법상 법정지상권을 포기한 것으로 본다."},{"판례":"대법원 판례(지료)","요지":"관습법상 법정지상권이 성립해도 건물 소유자는 대지 소유자에게 지료를 지급할 의무가 있다."},{"법령":"민법","조문":"민법 제366조(비교 조문)","원문":"저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"법령":"민법","조문":"민법 제287조(지료 연체와 소멸청구)","원문":"지상권자가 2년 이상의 지료를 지급하지 아니한 때에는 지상권설정자는 지상권의 소멸을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"무허가건물에도 성립하고(ㄱ) 증축 후에도 구 건물을 기준으로 인정되므로(ㄴ) 이 조합이 맞다."},{"번호":2,"판정":"틀림","설명":"ㄷ은 틀린 보기이고 옳은 ㄱ이 빠졌다. 대지 임대차계약의 체결은 법정지상권의 포기로 본다."},{"번호":3,"판정":"틀림","설명":"ㄷ은 지상권 포기로 보는 경우이고 ㄹ은 지료 지급 의무가 있는 경우라 둘 다 틀린 보기다."},{"번호":4,"판정":"틀림","설명":"ㄹ은 틀린 보기다. 법정지상권자는 지료를 지급할 의무가 있다."},{"번호":5,"판정":"틀림","설명":"ㄷ, ㄹ이 틀린 보기이고 옳은 ㄴ이 빠졌다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"건물이 건물로서의 요건을 갖췄다면 무허가건물이어도 관습법상 법정지상권이 인정된다는 것이 판례다."},{"기호":"ㄴ","판정":"옳음","설명":"성립 후 증축해도 구 건물을 기준으로 인정된다."},{"기호":"ㄷ","판정":"틀림","설명":"건물 취득 시 대지에 대한 임대차계약을 체결했다면 관습법상 법정지상권을 포기한 것으로 본다는 것이 판례다."},{"기호":"ㄹ","판정":"틀림","설명":"법정지상권자는 대지 소유자에게 지료를 지급할 의무가 있다."}],"개념":[{"종류":"표","제목":"저당권 경매의 법정지상권과 관습법상 법정지상권","머리":["구분","민법 제366조 법정지상권","관습법상 법정지상권"],"행":[["근거","민법 제366조","판례로 확립된 관습법"],["발생 원인","저당물의 경매로 토지와 건물의 소유자가 달라짐","매매 등으로 토지와 건물의 소유자가 달라짐"],["토지·건물 소유자","저당권 설정 당시 건물이 있고 동일인 소유","처분 당시 동일인 소유. 건물의 무허가·미등기는 불문"],["지료","당사자의 청구에 의하여 법원이 정함","지급 의무가 있고 협의가 안 되면 법원이 정함"],["지료 연체","2년 이상 지급하지 않으면 지상권설정자가 소멸청구(민법 제287조)","같은 규정이 적용됨(판례)"]]},{"종류":"비교","제목":"관습법상 법정지상권이 인정되는 경우와 부정되는 경우","왼쪽":{"이름":"인정","항목":["동일인 소유이던 건물만 매매 등으로 소유자가 달라진 경우","건물이 무허가·미등기인 경우","성립 후 건물을 증축·개축한 경우(구 건물 기준)"]},"오른쪽":{"이름":"부정","항목":["철거 특약이 있는 경우","건물 취득 시 대지 임대차계약을 체결해 지상권을 포기한 것으로 보는 경우","처분 전부터 토지와 건물의 소유자가 달랐던 경우"]}}],"함정":"ㄷ은 임대차계약의 체결을 지상권 포기로 보는 판례를 놓치면 옳게 읽힌다. ㄹ은 법정지상권이 성립했다고 지료까지 면제되는 것은 아니라는 점에서 틀린다."},"30회-2차-034":{"한줄":"乙이 건물의 인도와 사업자등록 신청을 마치지 못했다면 대항력이 없으므로, 건물을 매수한 丙의 인도청구에 대항할 수 없다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조의8","원문":"임차인의 차임연체액이 3기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"상가건물 임대차보호법","조문":"제11조제2항","원문":"제1항에 따른 증액 청구는 임대차계약 또는 약정한 차임 등의 증액이 있은 후 1년 이내에는 하지 못한다."},{"법령":"상가건물 임대차보호법","조문":"제10조제4항","원문":"임대인이 제1항의 기간 이내에 임차인에게 갱신 거절의 통지 또는 조건 변경의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 이 경우에 임대차의 존속기간은 1년으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제5조제2항","원문":"제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다."},{"법령":"상가건물 임대차보호법","조문":"제3조제1항","원문":"임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제3조제2항","원문":"임차건물의 양수인(그 밖에 임대할 권리를 승계한 자를 포함한다)은 임대인의 지위를 승계한 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"월차임 100만원이므로 200만원은 2기분이다. 해지는 연체액이 3기의 차임액에 달해야 한다(제10조의8)."},{"번호":2,"판정":"틀림","설명":"1년 제한은 증액청구에만 있다(제11조제2항). 감액에는 이런 제한이 없다."},{"번호":3,"판정":"틀림","설명":"임대차기간 만료 6개월 전부터 1개월 전까지 사이에 임대인이 갱신거절·조건변경 통지를 하지 않으면 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다(제10조제4항). 해지된 것으로 보지 않는다."},{"번호":4,"판정":"틀림","설명":"우선변제권은 후순위권리자나 그 밖의 채권자에 대한 것이다(제5조제2항). 선순위 저당권자보다 우선하지 못한다."},{"번호":5,"판정":"옳음","설명":"대항력은 건물의 인도와 사업자등록 신청이 있어야 생기고(제3조제1항) 양수인의 임대인 지위 승계(제3조제2항)도 대항력 있는 임대차를 전제로 하므로, 요건을 갖추지 못한 乙은 丙에게 대항할 수 없다."}],"개념":[{"종류":"표","제목":"상가건물 임차인의 대항력·우선변제권","머리":["구분","요건","효력 발생 시기"],"행":[["대항력(제3조제1항)","건물의 인도 + 사업자등록 신청","신청한 다음 날부터"],["우선변제권(제5조제2항)","대항요건 + 관할 세무서장의 확정일자","두 요건을 갖춘 때. 후순위권리자와 그 밖의 채권자에 우선"],["최우선변제(제14조제1항)","경매신청의 등기 전에 대항요건 구비 + 소액임차인","보증금 중 일정액을 담보물권자보다 우선"],["임차권등기(제6조제5항)","임대차 종료 후 보증금 미반환 시 등기명령 집행","등기를 마친 때 대항력·우선변제권 취득, 기존 권리는 유지"]]},{"종류":"흐름","제목":"계약갱신 관련 시기(제10조)","단계":[{"이름":"만료 6개월 전","설명":"임차인의 갱신요구 가능 시기 시작. 임대인의 갱신거절·조건변경 통지 기간도 이때부터 시작"},{"이름":"만료 1개월 전","설명":"갱신요구와 갱신거절·조건변경 통지의 마지막 시기"},{"이름":"통지 없는 경우","설명":"전 임대차와 동일한 조건으로 다시 임대차한 것으로 보고 존속기간은 1년"},{"이름":"갱신 후","설명":"임차인은 언제든지 해지를 통고할 수 있고 임대인이 받은 날부터 3개월 후 효력"},{"이름":"한도","설명":"임차인의 갱신요구권은 최초 임대차기간을 포함하여 10년 이내"}]}],"함정":"③은 통지를 하지 않았을 때의 효과가 해지가 아니라 동일 조건의 갱신이다. ①은 월 100만원 기준으로 200만원이 2기분임을 계산해야 한다. ⑤는 대항요건이 없는 임차인이 새 소유자에게 맞서지 못한다는 기본 규칙이다."},"30회-2차-036":{"한줄":"甲이 매매계약의 당사자이고 등기만 丙 명의로 한 3자간 등기명의신탁이다. 丙의 처분은 횡령죄가 되지 않고(ㄴ) 甲과 乙의 매매계약은 유효하여 甲이 乙에게 이전등기를 청구할 수 있으므로(ㄷ) ㄴ, ㄷ이 옳다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제1항","원문":"명의신탁약정은 무효로 한다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조제2항","원문":"명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다."},{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제8조 본문","원문":"다음 각 호의 어느 하나에 해당하는 경우로서 조세 포탈, 강제집행의 면탈(免脫) 또는 법령상 제한의 회피를 목적으로 하지 아니하는 경우에는 제4조부터 제7조까지 및 제12조제1항부터 제3항까지를 적용하지 아니한다."},{"판례":"대법원 전원합의체 판례(3자간 등기명의신탁의 횡령죄)","요지":"명의수탁자는 명의신탁자와 사이에 횡령죄를 구성할 위탁관계가 없으므로 부동산을 임의로 처분해도 횡령죄가 성립하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 틀린 보기이고 옳은 ㄴ이 빠졌다. 명의신탁약정은 목적을 묻지 않고 무효다."},{"번호":2,"판정":"틀림","설명":"ㄱ, ㄹ 모두 틀린 보기이고 옳은 ㄴ, ㄷ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"수탁자의 처분은 횡령죄가 아니고(ㄴ) 신탁자는 매도인에게 이전등기를 청구할 수 있으므로(ㄷ) 이 조합이 맞다."},{"번호":4,"판정":"틀림","설명":"ㄱ, ㄹ이 틀린 보기이고 옳은 ㄷ이 빠졌다."},{"번호":5,"판정":"틀림","설명":"ㄹ은 틀린 보기다. 3자간 유형에서 수탁자는 소유권을 취득하지 못하므로 신탁자의 부당이득반환청구권은 생기지 않는다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"명의신탁약정은 목적과 관계없이 무효다(제4조제1항). 목적을 따지는 예외는 종중·배우자·종교단체 특례뿐이다(제8조)."},{"기호":"ㄴ","판정":"옳음","설명":"3자간 등기명의신탁에서 수탁자가 부동산을 처분해도 신탁자에 대한 횡령죄가 성립하지 않는다는 것이 전원합의체 판례다."},{"기호":"ㄷ","판정":"옳음","설명":"매매계약은 유효하므로 甲은 乙에게 매매계약에 기한 소유권이전등기를 청구할 수 있다."},{"기호":"ㄹ","판정":"틀림","설명":"丙은 소유권을 취득하지 못한다(제4조제2항 본문). 甲은 대금을 乙에게 지급했으므로 丙에게 대금 상당의 부당이득반환을 청구할 수 없다."}],"개념":[{"종류":"표","제목":"부동산실명법 제8조 특례","머리":["대상","요건","효과"],"행":[["종중이 보유한 부동산을 종중 외의 자 명의로 등기","조세 포탈, 강제집행의 면탈, 법령상 제한의 회피를 목적으로 하지 않을 것","제4조~제7조, 제12조제1항~제3항 적용 제외"],["배우자 명의로 등기","위와 같음","위와 같음"],["종교단체 산하 조직이 보유한 부동산을 종교단체 명의로 등기","위와 같음","위와 같음"],["그 밖의 명의신탁","목적을 묻지 않음","약정 무효, 등기 무효, 형사처벌·과징금"]]},{"종류":"비교","제목":"3자간 등기명의신탁에서의 지위","왼쪽":{"이름":"명의신탁자(甲)","항목":["매도인과의 매매계약은 유효","매도인에게 소유권이전등기를 청구할 수 있음","매도인을 대위하여 수탁자 명의 등기의 말소를 청구할 수 있음","5년 이하의 징역 또는 2억원 이하의 벌금(제7조제1항)"]},"오른쪽":{"이름":"명의수탁자(丙)","항목":["등기가 무효여서 소유권을 취득하지 못함","대금 상당 부당이득반환 의무가 없음(대금은 매도인에게 지급됨)","부동산을 임의로 처분해도 횡령죄가 성립하지 않음","3년 이하의 징역 또는 1억원 이하의 벌금(제7조제2항)"]}}],"함정":"ㄱ은 목적이 없으면 유효하다고 본 점이 틀렸다. 목적을 따지는 특례는 종중·배우자·종교단체뿐이다. ㄹ은 계약명의신탁에서 매도인이 선의인 경우의 구제수단을 3자간 유형에 가져다 쓴 보기다."},"30회-2차-038":{"한줄":"부동산거래계약시스템으로 거래계약을 체결하면 계약이 체결된 때에 부동산거래계약 신고서를 제출한 것으로 본다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"거래신고법 제25조","원문":"국토교통부장관은 효율적인 정보의 관리 및 국민편의 증진을 위하여 대통령령으로 정하는 바에 따라 부동산거래 및 주택 임대차의 계약ㆍ신고ㆍ허가ㆍ관리 등의 업무와 관련된 정보체계를 구축ㆍ운영할 수 있다. 제5장의2 보칙"},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"시행규칙 제2조제14항","원문":"법 제25조에 따라 구축된 부동산 거래계약 관련 정보시스템(이하 \"부동산거래계약시스템\"이라 한다)을 통하여 부동산 거래계약을 체결한 경우에는 부동산 거래계약이 체결된 때에 제1항, 제2항 또는 제4항의 부동산거래계약 신고서를 제출한 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"시행령 제19조의5제2항","원문":"제1항에 따라 전자문서로 제출하는 경우에는 「전자서명법」 제2조제6호에 따른 인증서(서명자의 실지명의를 확인할 수 있는 것으로 한정한다)를 통한 본인확인의 방법으로 서명 또는 날인할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"거래신고법 제6조의5제3항","원문":"제6조의2, 제6조의3에 따른 신고의 접수를 완료한 때에는 「주택임대차보호법」 제3조의6제1항에 따른 확정일자를 부여한 것으로 본다(임대차계약서가 제출된 경우로 한정한다)."},{"법령":"주택임대차계약증서의 확정일자 부여 및 정보제공에 관한 규칙","조문":"확정일자 규칙 제6조제2항","원문":"다음 각 호의 자는 인터넷등기소에서 전자확정일자 부여를 신청할 수 있다. 1. 해당 주택의 임대인ㆍ임차인 2. 변호사 또는 법무사[법무법인, 법무법인(유한), 법무조합, 법무사법인, 법무사법인(유한)을 포함한다. 이하 \"자격자대리인\"이라 한다] 3. 해당 주택의 주택임대차계약증서를 작성한 개업공인중개사"},{"법령":"공인중개사법","조문":"공인중개사법 제25조제3항","원문":"개업공인중개사는 중개가 완성되어 거래계약서를 작성하는 때에는 제1항에 따른 확인ㆍ설명사항을 대통령령으로 정하는 바에 따라 서면으로 작성하여 거래당사자에게 교부하고 대통령령으로 정하는 기간 동안 그 원본, 사본 또는 전자문서를 보존하여야 한다. 다만, 확인ㆍ설명사항이 「전자문서 및 전자거래 기본법」 제2조제9호에 따른 공인전자문서센터(이하 \"공인전자문서센터\"라 한다)에 보관된 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부동산거래·주택임대차의 계약·신고·허가·관리 등의 정보체계를 구축·운영할 수 있는 사람은 국토교통부장관이다(제25조). 시·도지사가 아니며 의무도 아니다."},{"번호":2,"판정":"틀림","설명":"전자문서로 신고할 때에는 인증서를 통한 본인확인의 방법으로 서명 또는 날인할 수 있다(시행령 제19조의5제2항). 전자인증으로 신분을 증명할 수 있다."},{"번호":3,"판정":"틀림","설명":"주택임대차계약증서의 전자확정일자는 해당 주택의 임대인·임차인, 계약증서를 작성한 개업공인중개사 등이 인터넷등기소에서 신청할 수 있다(확정일자 규칙 제6조제2항). 전자계약으로 체결했다는 이유로 임차인의 신청이 막히지 않는다."},{"번호":4,"판정":"옳음","설명":"부동산거래계약시스템을 통하여 거래계약을 체결한 경우 계약이 체결된 때에 부동산거래계약 신고서를 제출한 것으로 본다(시행규칙 제2조제14항)."},{"번호":5,"판정":"틀림","설명":"확인·설명사항이 공인전자문서센터에 보관된 경우에는 개업공인중개사가 서면 또는 전자문서로 보존하지 않아도 된다(공인중개사법 제25조제3항 단서)."}],"개념":[{"종류":"표","제목":"부동산거래계약시스템 이용 시 신고 의제","머리":["대상","의제 내용","근거"],"행":[["부동산 거래계약 체결","거래계약이 체결된 때에 부동산거래계약 신고서를 제출한 것으로 봄","시행규칙 제2조제14항"],["거래계약 해제등","해제등이 이루어진 때에 해제등 신고서를 제출한 것으로 봄","시행규칙 제4조제4항"],["주택 임대차 계약 체결","임대차계약당사자가 공동으로 임대차 신고서를 제출한 것으로 봄","시행규칙 제6조의2제8항"],["주택 임대차 신고 접수","임대차계약서가 제출된 경우 확정일자를 부여한 것으로 봄","거래신고법 제6조의5제3항"]]},{"종류":"표","제목":"중개대상물 확인·설명서의 작성·교부·보존","머리":["구분","내용","근거"],"행":[["작성·교부","중개가 완성되어 거래계약서를 작성하는 때 서면으로 작성하여 거래당사자에게 교부","법 제25조제3항, 영 제21조제3항"],["보존 기간","3년","영 제21조제4항"],["보존 방법","원본, 사본 또는 전자문서","법 제25조제3항"],["보존 면제","확인·설명사항이 공인전자문서센터에 보관된 경우","법 제25조제3항 단서"],["서명 및 날인","개업공인중개사, 해당 중개행위를 한 소속공인중개사가 함께","법 제25조제4항"]]}],"함정":"⑤는 전자 보관을 해도 서면 보존이 남는다고 생각하기 쉽다. 공인전자문서센터에 보관되면 보존 의무가 면제된다. ①은 주체가 시·도지사가 아니라 국토교통부장관이고, 구축·운영은 의무가 아니라 할 수 있는 임의 규정이다."}};